'use strict';
(function(){
const D=globalThis.RA.D;
const q=(prompt,answer,d1,d2,explain,sense=1,type='meaning')=>({prompt,answer,d1,d2,explain,sense,type});
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const M=(wrong,right,reason,errorType='meaning')=>({errorType,wrong,right,reason});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:w==='parisyllabic'?'Larousse: https://www.larousse.fr/dictionnaires/francais/parisyllabique/58215':'Etymonline: https://www.etymonline.com/word/'+w.toLowerCase().replaceAll(' ','-')});
const P=(w,origin,c,m,qs)=>D(w,{etymology:E(origin,w),contexts:Array.isArray(c)?c:[c],mistakes:[m],quiz:qs.map((x,i)=>({id:w+'.q'+(i+1),senseId:w+'.s'+x.sense,type:'辨义与用法',prompt:x.prompt,options:[x.answer,x.d1,x.d2],answer:x.answer,explain:x.explain,errorType:x.type}))});
P('paleontology','Paleontology was coined in the 1830s, probably from French paléontologie, combining Greek palaios “ancient” with ontology, the study of being.',C('paleontology.s1','古生物学','Paleontology students compared fossil shells from two rock layers to reconstruct an ancient marine ecosystem.','古生物学专业的学生比较了两个岩层中的贝类化石，以重建古代海洋生态系统。','Paleontology students compared fossil shells / from two rock layers / to reconstruct an ancient marine ecosystem.','paleontology 通过化石研究地质时期的生物。','贝类化石是过去生物的保存遗迹。'),M('Paleontology reconstructs ancient life from fossils, but this class used only living fish and no fossil evidence.','The paleontology class reconstructed ancient life by comparing fossil shells from different rock layers.','没有化石证据就不能说研究是通过化石重建过去生物。','meaning'),[q('What evidence did the students compare?','fossil shells from two rock layers','fresh shells gathered from an aquarium','modern spelling samples from two books','学生比较了两个岩层中的贝类化石。'),q('What does paleontology study?','past organisms through their fossils','the colour choices in a painting','the way a living animal digests food','古生物学研究化石中的过去生物。',1,'meaning'),q('What did the fossils help reconstruct?','an ancient marine ecosystem','the students’ current classroom','a modern hospital network','贝类化石帮助重建古代海洋生态系统。',1,'context'),q('Which Greek element in paleontology means “ancient”?','palaios','ontos','logos','palaios 表示古老。',1,'word-formation')]);
P('palette','Palette came through French from Old French palete, “small shovel,” ultimately Latin pala; it first named an artist’s colour-mixing board and later a set of colours.',[C('palette.s1','调色板；配色','The painter squeezed blue and ochre onto her palette, then mixed a green that matched the marsh grass.','画家把蓝色和赭色挤到调色板上，调出一种与沼泽草地相配的绿色。','The painter squeezed blue and ochre onto her palette / then mixed a green / that matched the marsh grass.','palette 可指调色板，也可指使用的一组颜色。','颜料先放在板上混合。'),C('palette.s1','调色板；配色','The designer kept a muted palette of olive, cream, and charcoal across every page of the guide.','设计师在指南的每一页都统一使用橄榄绿、奶油色和炭灰色的柔和配色。','The designer kept a muted palette / of olive, cream, and charcoal / across every page of the guide.','palette 也可指某作品或设计所采用的颜色组合。','列出的三种色彩构成配色方案。')],M('The painter mixed all the colours directly on a finished canvas, but the sentence calls that canvas her wooden palette.','The painter mixed the colours on a wooden palette before applying them to the canvas.','画布是作画表面；调色板是混合颜料用的板。','distinction'),[q('Where did the painter first squeeze the blue and ochre?','onto her palette','onto the finished canvas only','onto the museum wall','颜料先挤在调色板上混合。'),q('Which set forms the designer’s palette?','olive, cream, and charcoal','red, violet, and gold','blue, ochre, and white only','指南使用橄榄绿、奶油色和炭灰色。',1,'context'),q('Which use means a chosen range of colours?','a muted palette for the guide’s pages','a wooden palette with a thumb hole','a pan used to heat pigments','这里 palette 指设计采用的颜色组合。',1,'meaning'),q('What was palette’s older literal referent?','a flat board for mixing paint','a printed book with no images','a brush for erasing pencil lines','palette 原指调色用的薄板。',1,'word-formation')]);
P('palimpsest','Palimpsest comes from Greek palimpsestos, “scraped again”; it was a manuscript surface reused after earlier writing was erased.',C('palimpsest.s1','重写羊皮纸','Under ultraviolet light, the conservator found traces of an older prayer beneath the later text on the palimpsest.','在紫外线下，修复师发现这份重写羊皮纸的后层文字下还留有更早祷文的痕迹。','Under ultraviolet light / the conservator found traces of an older prayer / beneath the later text on the palimpsest.','palimpsest 是擦去旧文字后再写新文字、但仍留有旧痕的文稿。','较早的祷文痕迹仍在后来文字之下。'),M('The conservator called the page a palimpsest even though it had never been written on before and showed no erased text.','The conservator identified a palimpsest because erased earlier writing remained beneath the later text.','没有被擦除的旧文字痕迹，就没有重写文稿的关键特征。','meaning'),[q('What did the conservator find under the later text?','traces of an older prayer','a new palette of paint','a fossil shell','旧祷文的痕迹仍在后来的文字下方。'),q('What is a palimpsest?','a reused writing surface with erased earlier text beneath later writing','a page that has never been written on','a pamphlet printed in several colours','它是旧字被擦后重新书写、仍留旧痕的文稿。',1,'meaning'),q('What revealed the earlier prayer?','ultraviolet light','a paint-mixing board','a geological layer','紫外线显出下层文字。',1,'context'),q('Why is “scraped again” relevant to the word’s origin?','the writing surface was scraped before being reused','the manuscript was painted on a palette','the page was folded into a pamphlet','古代重用书写材料前会刮除旧字。',1,'word-formation')]);
P('palliate','Palliate comes from Medieval Latin palliatus, literally “cloaked,” from palliare “cover with a cloak”; it means lessen symptoms or make an offence seem less serious.',[C('palliate.s1','缓和；减轻','The new medicine palliated the patient’s pain for several hours but did not cure the underlying infection.','新药让患者的疼痛缓解了几个小时，但没有治愈根本感染。','The new medicine palliated the patient’s pain / for several hours / but did not cure the underlying infection.','palliate 指减轻症状或严重程度，而非彻底治愈或开脱。','疼痛减轻，但感染仍存在。'),C('palliate.s1','缓和；减轻','The official cited the storm damage to palliate the agency’s delay, though the missed warnings remained serious.','官员以风暴损害为由淡化机构的延误，但错过预警仍是严重问题。','The official cited the storm damage / to palliate the agency’s delay / though the missed warnings remained serious.','palliate 也可指提出理由以减轻过失的严重性。','解释试图减轻责任，但并未完全免责。')],M('The treatment palliated the infection by completely eliminating the bacteria and curing the patient.','The treatment palliated the patient’s symptoms without eliminating the underlying infection.','palliate 是缓解而非根治；若彻底杀菌治愈，就超出了该词义。','distinction'),[q('What effect did the medicine have?','it eased pain for several hours','it cured the infection permanently','it erased the patient’s medical record','药物暂时缓解了疼痛，并未治愈感染。'),q('What did the official try to palliate?','the agency’s delay','the storm’s rainfall','the patient’s infection','官员试图淡化机构延误的严重性。',1,'context'),q('Which action palliates a symptom?','reducing pain without curing its cause','eliminating the illness completely','pretending the patient has no pain','缓解症状而不根治病因是 palliate。',1,'meaning'),q('The “cloak” image in palliate suggests?','covering or making something seem less severe','revealing every detail openly','scraping off old writing','词源中的“披上外衣”引申为遮掩或减轻严重性。',1,'word-formation')]);
P('palm','Palm of the hand and palm tree share Latin palma, “palm of the hand”; the tree’s leaves were compared to spread fingers, and the verb developed from hiding something in the hand.',[C('palm.s1','手掌；掌心','The nurse placed the small seed in the child’s open palm and asked her to close her fingers gently.','护士把一粒小种子放在孩子摊开的手掌上，请她轻轻合拢手指。','The nurse placed the small seed / in the child’s open palm / and asked her to close her fingers gently.','palm 指手腕与手指之间的手掌内侧。','种子放在摊开的掌心。'),C('palm.s2','棕榈树','A tall palm shaded the beach path with its crown of long leaves.','一棵高大的棕榈树用顶端的长叶为海滩小路遮阴。','A tall palm shaded the beach path / with its crown / of long leaves.','palm 也指树干高直、顶部生长大型叶片的热带树。','顶端成簇的长叶显示这里指棕榈树。'),C('palm.s3','把……藏在手心；蒙混拿走','The card player palmed the spare card while the dealer turned to check the score.','发牌员转身核对比分时，牌手把多余的一张牌藏进了手掌。','The card player palmed the spare card / while the dealer turned / to check the score.','palm 作动词可表示把小物藏在手掌中，或以此进行欺骗。','多余的牌被藏在手心。')],M('The card player palmed the spare card by placing it openly on the table for everyone to inspect.','The card player palmed the spare card by concealing it in the hand.','公开放在桌面供人检查不是藏在手心。','meaning'),[q('Where did the nurse place the seed?','in the child’s open hand','on the beach path','under the dealer’s score sheet','种子放在孩子摊开的手掌里。'),q('What shaded the beach path?','a tall palm tree','a child’s palm','a hidden playing card','棕榈树用长叶遮住小路。',2,'context'),q('How did the card player palm the spare card?','he concealed it in his hand','he planted it beside a palm tree','he showed it openly to the dealer','palm 作动词表示藏在掌中。',3,'context'),q('Which sense appears in “the palm of her hand”?','the inner surface of the hand','a tropical tree','to hide a card in the hand','该短语指手掌内侧。',1,'meaning')]);
P('palpable','Palpable comes from Latin palpabilis, “that may be touched,” from palpare “to touch gently”; it means tangible or unmistakably obvious.',C('palpable.s1','可感知的；显而易见的','A palpable tension filled the courtroom when the jury returned after only twenty minutes.','陪审团仅离开二十分钟便返回法庭，现场顿时充满明显的紧张气氛。','A palpable tension filled the courtroom / when the jury returned / after only twenty minutes.','palpable 可指能被触摸，也可比喻感官或心智上明显可察觉。','所有人都能感到气氛紧张。'),M('There was palpable tension in the silent courtroom, but every observer agreed that no one could notice or sense any tension.','There was palpable tension in the courtroom, which observers could readily sense.','palpable 表示明显可感知；说没人能察觉与此相反。','meaning'),[q('When did tension fill the courtroom?','when the jury returned quickly','while the jury was absent for several weeks','when the courthouse closed permanently','陪审团很快返回时，法庭气氛变得紧张。'),q('What does palpable mean in “palpable tension”?','clearly felt or noticed','physically weighed on a scale','hidden from every observer','这里指紧张明显到可以感知。',1,'meaning'),q('Which is a palpable improvement?','a change every visitor can immediately see','a private change no one can detect','a theoretical change with no evidence','人人都能立刻看到的改善是明显的。',1,'context'),q('What does the Latin source palpabilis literally suggest?','capable of being touched','capable of being erased','belonging to a palette','其词源表示可以触摸的。',1,'word-formation')]);
P('palpitate','Palpitate comes from Latin palpitare, “to throb or flutter”; it describes a heart beating fast or irregularly.',C('palpitate.s1','（心脏）悸动','After sprinting up the stairs, Leo felt his heart palpitate until he sat down and rested.','冲上楼梯后，利奥感到心脏一阵急促跳动，直到坐下休息才缓和。','After sprinting up the stairs / Leo felt his heart palpitate / until he sat down and rested.','palpitate 描述心脏快速或不规则地跳动。','剧烈运动后心跳急促。'),M('After sprinting, Leo’s heart palpitated steadily at a slow, perfectly regular rate.','After sprinting, Leo’s heart palpitated rapidly and irregularly until he rested.','palpitate 描述急促或不规则心跳，不是缓慢且完全规律的心率。','meaning'),[q('What made Leo’s heart palpitate?','sprinting up the stairs','reading a pamphlet while seated','painting a calm landscape','冲楼梯后他的心脏急促跳动。'),q('What does palpitate describe?','a heart beating quickly or irregularly','a hand hiding a playing card','a colour mixed on a board','palpitate 描述心脏快速或不规则地跳动。',1,'meaning'),q('When did Leo’s heartbeat settle?','after he sat down and rested','before he began running','only after the stairs were removed','他坐下休息后心跳才缓和。',1,'context'),q('Which sentence uses palpitate naturally?','Her heart began to palpitate during the steep climb.','The palette palpitated across the canvas.','The pamphlet palpitated the committee.','心脏在爬陡坡时悸动，符合该词用法。',1,'usage')]);
P('paltry','Paltry is of uncertain origin; it has long described something contemptibly small, poor, or unimportant.',C('paltry.s1','微不足道的；少得可怜的','The museum received a paltry donation that covered only a fraction of the roof repairs.','博物馆收到的捐款少得可怜，只够支付一小部分屋顶维修费。','The museum received a paltry donation / that covered only a fraction / of the roof repairs.','paltry 表示数量小或价值低到不值得重视。','捐款远不足以支付维修费。'),M('The paltry donation covered the entire restoration and left enough money for several new buildings.','The paltry donation covered only a small part of the restoration cost.','paltry 表示少得可怜，不能覆盖全部工程还剩余大量资金。','meaning'),[q('What did the museum’s donation cover?','only part of the roof repairs','the entire restoration plus new buildings','the painter’s full palette','少量捐款只能支付一小部分维修费。'),q('What does paltry mean?','too small or unimportant to matter much','remarkably large and generous','obvious to every observer','paltry 表示微不足道或少得可怜。',1,'meaning'),q('Which amount is paltry for a major bridge repair?','a few coins that cover almost none of the cost','a grant that pays every invoice','a fund larger than the whole project budget','几枚硬币无法支付维修费，数额微小。',1,'context'),q('How certain is the word’s origin in this note?','the origin is uncertain','it definitely comes from Greek “all healing”','it is certainly from Latin for “palm tree”','词源资料未能确定 paltry 的来源。',1,'word-formation')]);
P('pamper','Pamper is of uncertain deeper origin; it developed in English for treating someone with excessive care, comfort, or indulgence.',C('pamper.s1','娇惯；纵容','The hotel pampered its guests with warm towels, late breakfasts, and a quiet room overlooking the garden.','酒店用热毛巾、延迟早餐和俯瞰花园的安静客房悉心款待客人。','The hotel pampered its guests / with warm towels, late breakfasts, / and a quiet garden-view room.','pamper 表示给予过多照顾、舒适或纵容。','客人享受到格外周到舒适的待遇。'),M('The hotel pampered its guests by refusing clean towels, cancelling breakfast, and leaving them in an uncomfortable room.','The hotel pampered its guests with clean towels, a generous breakfast, and a comfortable room.','拒绝舒适服务是苛待而非娇宠客人。','meaning'),[q('How did the hotel pamper its guests?','with warm towels and comfortable service','by cancelling breakfast and removing towels','by asking them to repair the garden','酒店给客人提供毛巾、早餐和舒适客房。'),q('What does pamper mean?','treat with excessive care or indulgence','criticize a performance severely','reduce a symptom without curing it','pamper 指给予过多照顾或纵容。',1,'meaning'),q('Which action pampers a child?','letting the child choose treats and doing every small task for them','making the child walk home in a storm','asking the child to share a toy once','包办一切并给予额外享受是娇宠。',1,'context'),q('Is the origin of pamper stated as certain here?','No, its deeper origin is uncertain.','Yes, it certainly means “ancient being.”','Yes, it comes from the name of a Greek god.','该词更深层来源未确定。',1,'word-formation')]);
P('pamphlet','Pamphlet is from Anglo-Latin panfletus, probably a popular short form of the medieval poem Pamphilus, seu de Amore; its modern senses include an unbound booklet and a brief argumentative essay.',[C('pamphlet.s1','小册子；宣传册','The clinic gave each visitor a thin pamphlet explaining how to prepare for the screening.','诊所给每位访客一本薄薄的小册子，说明筛查前的准备事项。','The clinic gave each visitor a thin pamphlet / explaining how to prepare / for the screening.','pamphlet 可指简短、未装订成厚书的信息册。','小册子提供筛查说明。'),C('pamphlet.s2','时论小册；论战文章','In her pamphlet, the reformer argued that the voting system excluded rural communities.','改革者在她的时论小册中主张，投票制度排斥了乡村社区。','In her pamphlet / the reformer argued that the voting system / excluded rural communities.','pamphlet 也可指表达立场或倡议的短篇印刷文章。','文本以论证制度改革为目的。')],M('The clinic gave patients a pamphlet, a large bound encyclopedia containing thousands of pages.','The clinic gave patients a pamphlet, a thin unbound booklet with screening instructions.','pamphlet 是薄而简短的小册子，不是大型多卷百科全书。','distinction'),[q('What did the clinic’s pamphlet explain?','how to prepare for screening','how to mix a palette of paint','how to treat a pancreatic disorder','小册子说明筛查前如何准备。'),q('What argument did the reformer make?','the voting system excluded rural communities','the clinic should cancel all screenings','the pamphlet was a bound encyclopedia','时论小册论证了投票制度排斥乡村社区。',2,'context'),q('Which item is a pamphlet?','a thin unbound booklet describing a public service','a multi-volume hardbound encyclopedia','a one-page painting palette','薄而未装订的信息册是 pamphlet。',1,'meaning'),q('Which pamphlet sense is used in the reformer example?','a short printed essay arguing for a cause','a thin instruction booklet only','a handwritten palimpsest','改革者用小册子表达政治主张，属论战文章义。',2,'meaning')]);

P('pan','Pan as a cooking vessel comes from Old English panne, from a Germanic word for a shallow dish; it is distinct from Greek pan-, “all.”',[C('pan.s1','平底锅；烤盘','She warmed the oil in a heavy pan before adding onions and sliced mushrooms.','她先在厚底锅里加热油，再放入洋葱和蘑菇片。','She warmed the oil in a heavy pan / before adding onions / and sliced mushrooms.','pan 指用于炉灶烹饪的圆形金属容器。','锅中加热油后再放食材。'),C('pan.s2','严厉批评','Several reviewers panned the film for copying its plot from an older adventure story.','几位评论家严厉批评这部电影，称其照搬了旧冒险故事的情节。','Several reviewers panned the film / for copying its plot / from an older adventure story.','pan 作动词可表示对电影、书或演出进行严厉批评。','影评人因情节抄袭而批评电影。'),C('pan.s3','（镜头）摇摄；扫视','The camera panned left to follow the runner as she crossed the finish line.','跑者冲过终点线时，摄像机向左摇摄跟拍。','The camera panned left / to follow the runner / as she crossed the finish line.','pan 作动词也可表示使摄像机水平转动跟随画面。','镜头向左跟随跑者。')],M('The critic panned the film by praising every scene and recommending it as the year’s best picture.','The critic panned the film, condemning its copied plot and poor acting.','pan 作评论动词表示严厉批评，不是赞扬。','meaning'),[q('What did she warm in the pan?','oil','a camera lens','a printed pamphlet','她在锅中加热油。'),q('Why did reviewers pan the film?','they said it copied an older story','they admired its original plot','they disliked the camera’s leftward movement','评论家批评电影抄袭旧故事。',2,'context'),q('What did the camera do at the finish line?','it panned left to follow the runner','it criticized the runner’s performance','it heated oil for the runner','镜头向左摇摄跟拍跑者。',3,'context'),q('Which use of pan is the cooking vessel?','a metal pan on the stove','reviewers pan a film','the camera pans to the left','第一项中 pan 指烹饪用锅。',1,'meaning')]);
P('panacea','Panacea comes from Greek panakeia, “all-healing,” from pan “all” and akos “remedy”; it means a supposed cure for every disease or problem.',C('panacea.s1','万能药，灵丹妙药','The mayor warned that a new app was no panacea for traffic because roads, buses, and housing also mattered.','市长提醒说，新应用并非解决交通问题的灵丹妙药，因为道路、公交和住房同样重要。','The mayor warned that a new app was no panacea / for traffic / because roads, buses, and housing also mattered.','panacea 常用于否定句，表示不能解决所有问题的万能方案。','交通问题涉及多个方面，应用程序无法包治百病。'),M('The mayor called the app a panacea because it could not solve any traffic problem or improve any journey.','The mayor said the app was no panacea because it could not solve every traffic problem by itself.','panacea 指被认为能解决所有问题的方案，不是完全无用之物。','meaning'),[q('What did the mayor say the app could not solve alone?','the traffic problem','the city’s spelling system','the museum’s roof repairs','市长说应用程序不能单独解决交通问题。'),q('What does panacea mean?','a supposed cure for every problem','a small booklet arguing for reform','a medical organ that releases hormones','panacea 指万能药或万能方案。',1,'meaning'),q('Why was the app not a panacea?','roads, buses, and housing also affected traffic','the app was the only factor in the city','traffic had already disappeared','交通还受道路、公交和住房影响。',1,'context'),q('Which sentence uses panacea correctly?','One new rule is no panacea for every workplace conflict.','The panacea contained only a few pages.','The camera panned across the panacea.','第一句表示一条新规不能解决所有职场冲突。',1,'meaning')]);
P('pancreas','Pancreas comes from Greek pankreas, literally “entirely flesh,” from pan “all” and kreas “flesh.”',C('pancreas.s1','胰腺','The scan showed that the pancreas was inflamed, so the doctor ordered further tests of the digestive system.','扫描显示胰腺发炎，因此医生安排了进一步的消化系统检查。','The scan showed that the pancreas was inflamed / so the doctor ordered / further digestive-system tests.','pancreas 是向肠道释放消化液、并向血液释放激素的器官。','炎症出现在该器官。'),M('The pancreas releases insulin and digestive juices, but the report described it as the bone that protects the lungs.','The pancreas releases hormones and digestive juices, and the scan showed inflammation in that organ.','胰腺是腺体器官，不是保护肺部的骨骼。','distinction'),[q('What did the scan show?','inflammation in the pancreas','a fracture in the rib cage','an outcry in the digestive system','扫描显示胰腺发炎。'),q('What does the pancreas release?','digestive juices and hormones','paint pigments and ink','air from the lungs only','胰腺释放消化液和激素。',1,'meaning'),q('What did the doctor order after the scan?','further digestive-system tests','a pamphlet about Greek grammar','a camera pan across the clinic','医生安排了进一步的消化系统检查。',1,'context'),q('Which word element in pancreas means “all”?','pan-','kreas','-ic','pan- 表示“全部”。',1,'word-formation')]);
P('pancreatic','Pancreatic is formed from pancreas with the adjective suffix -ic; it means relating to or affecting the pancreas.',C('pancreatic.s1','胰的','The laboratory measured pancreatic enzymes in the blood sample to investigate the patient’s abdominal pain.','实验室检测了血样中的胰腺酶，以调查患者的腹痛。','The laboratory measured pancreatic enzymes / in the blood sample / to investigate the abdominal pain.','pancreatic 表示与胰腺有关或影响胰腺的。','酶来自胰腺并在血液样本中检测。'),M('The report described pancreatic enzymes as produced by the lungs and unrelated to the pancreas.','The report described pancreatic enzymes as related to the pancreas and measured them in the blood.','pancreatic 就是与胰腺相关，不能说它与胰腺无关。','meaning'),[q('What did the laboratory measure?','pancreatic enzymes in blood','the patient’s palm temperature','a pane of window glass','实验室检测了血液中的胰腺酶。'),q('What does pancreatic mean?','related to or affecting the pancreas','belonging to the lungs','describing a broad landscape view','pancreatic 表示与胰腺有关。',1,'meaning'),q('Why were the enzymes measured?','to investigate abdominal pain','to identify a red panda','to criticize a film','检测用于调查患者腹痛。',1,'context'),q('Which noun is the base of pancreatic?','pancreas','panacea','panorama','pancreatic 由 pancreas 加 -ic 构成。',1,'word-formation')]);
P('panda','Panda was first recorded in English in the 1830s for the Himalayan red panda, apparently from a Nepalese name; the giant panda later received the same name.',[C('panda.s1','大熊猫；熊猫','The giant panda spent the morning stripping bamboo leaves with its broad molars.','大熊猫上午一直用宽大的臼齿剥食竹叶。','The giant panda spent the morning / stripping bamboo leaves / with its broad molars.','panda 常指原产中国、主要以竹子为食的黑白色大熊。','竹叶和宽臼齿对应大熊猫的食性。'),C('panda.s2','小熊猫','The red panda curled its long ringed tail around its body while resting on a branch.','小熊猫休息时把长长的环纹尾巴绕在身体周围。','The red panda curled its long ringed tail / around its body / while resting on a branch.','panda 也可指体型较小、红褐色且有长环纹尾巴的小熊猫。','红褐色和环纹尾巴提示小熊猫。')],M('The giant panda ate bamboo, while the red panda was described as a black-and-white bear with no ringed tail.','The giant panda ate bamboo, while the red panda was reddish and had a long ringed tail.','大熊猫和小熊猫的体色与尾部特征不能互相混淆。','distinction'),[q('What did the giant panda eat?','bamboo leaves','fish from the estuary','paint from a palette','大熊猫主要吃竹子。'),q('What did the red panda do with its tail?','curled its long ringed tail around its body','used it to mix paint','hid it beneath a pamphlet','小熊猫把长环纹尾巴绕在身上。',2,'context'),q('Which animal is the giant panda in this entry?','a black-and-white bear-like animal from China','a small reddish Himalayan animal','a fish-catching hawk','大熊猫是中国的黑白色熊类动物。',1,'meaning'),q('Which panda was named first in English?','the smaller Himalayan red panda','the giant panda from China','both names first appeared together','英语中 panda 最早指喜马拉雅小熊猫。',2,'word-formation')]);
P('pandemic','Pandemic comes from Greek pandemos, “pertaining to all people,” from pan “all” and demos “people”; it describes disease spread across a country or the world.',C('pandemic.s1','大流行病','During the pandemic, hospitals in several countries coordinated supplies as infections crossed national borders.','大流行病期间，感染跨越国界，多国医院协调医疗物资。','During the pandemic / hospitals in several countries coordinated supplies / as infections crossed national borders.','pandemic 指疾病在整个国家或世界范围广泛传播。','疫情在多个国家之间传播。'),M('The disease was called a pandemic even though it remained in one small village and never spread beyond a few households.','The disease became a pandemic after it spread widely across countries and regions.','局限在少数家庭的局部疫情不符合跨国或全球广泛传播的 pandemic。','distinction'),[q('What did hospitals coordinate?','medical supplies','a colour palette','a film review','多国医院协调医疗物资。'),q('What makes an illness a pandemic?','it spreads across a country or the world','it affects one person in one household','it is caused by an inflamed pancreas','pandemic 指大范围传播的疾病。',1,'meaning'),q('Where did the infections spread?','across national borders','only inside one clinic','through one window pane','感染跨越了国家边界。',1,'context'),q('The Greek element demos means?','people','all','disease','demos 表示“人民”。',1,'word-formation')]);
P('pandemonium','Pandemonium was coined by Milton for “the place of all demons,” from Greek pan “all” and daimōn “spirit”; it now means uproar and confusion.',C('pandemonium.s1','一片混乱','Pandemonium broke out in the station when two cancelled trains were announced at once.','车站同时宣布两班列车取消后，现场顿时一片混乱。','Pandemonium broke out in the station / when two cancelled trains / were announced at once.','pandemonium 指嘈杂、喧闹且难以控制的混乱场面。','多班列车取消引发乘客骚动。'),M('Pandemonium broke out in the station, where everyone remained silent, orderly, and unaware of the cancellations.','Pandemonium broke out when passengers shouted and crowded the service desks after the cancellations.','安静有序且毫不知情的场面不是混乱喧闹。','meaning'),[q('Where did pandemonium break out?','at the station','in a quiet art studio','inside the pancreas','车站公告后现场混乱起来。'),q('What triggered the commotion?','two trains were cancelled at once','a painter mixed colours','a red panda climbed a tree','两班列车同时取消引发骚动。',1,'context'),q('What does pandemonium mean?','uproar and confusion','a worldwide disease','a thin information booklet','pandemonium 表示喧闹混乱。',1,'meaning'),q('Milton’s original Pandemonium was imagined as?','the place of all demons','the study of ancient fossils','a public transport station','Milton 用它命名“所有恶魔之地”。',1,'word-formation')]);
P('pane','Pane came through Old French pan, “piece or panel”; it refers to one sheet of glass fitted into a window or door.',C('pane.s1','窗格玻璃','A cracked pane in the greenhouse was replaced before the cold night arrived.','温室里一块破裂的窗格玻璃在寒夜到来前被换掉了。','A cracked pane in the greenhouse / was replaced / before the cold night arrived.','pane 指窗户或门里的一整片玻璃。','破裂的玻璃片被单独更换。'),M('The worker replaced one pane by removing the entire greenhouse and leaving all its glass sheets untouched.','The worker replaced the cracked pane with a new sheet of window glass.','更换单块玻璃而不是拆走整个温室，才对应 pane 的窗格玻璃义。','meaning'),[q('What was replaced in the greenhouse?','a cracked sheet of glass','the entire roof structure','a pamphlet on plant care','被换掉的是一块破裂的玻璃。'),q('What does pane mean here?','one sheet of glass in a window','a wooden frame around a window','a sheet of paper in a pamphlet','pane 指窗户中的一片玻璃。',1,'meaning'),q('When was the cracked pane replaced?','before the cold night','after the greenhouse was demolished','during a pandemic','玻璃在寒夜到来前更换。',1,'context'),q('Which object has panes?','a greenhouse window divided into glass sections','a glassless wooden door','an unbound pamphlet','分格玻璃窗由多个 pane 组成。',1,'meaning')]);
P('panel','Panel came from Old French panel, “piece of cloth or section”; it can be a flat section, an expert group, a control board, or the act of covering with panels.',[C('panel.s1','嵌板；镶板；墙板','The carpenter replaced a warped wooden panel in the classroom door.','木匠更换了教室门上一块变形的木嵌板。','The carpenter replaced a warped wooden panel / in the classroom door.','panel 作名词可指门、墙或其他表面的一块平面板材。','门由一块块平板组成。'),C('panel.s2','专家小组；讨论小组','A panel of climate scientists answered questions from students after the lecture.','讲座结束后，一组气候科学家回答了学生的问题。','A panel of climate scientists answered questions / from students / after the lecture.','panel 也可指受邀回答问题或提供建议的一组人。','科学家组成小组回答提问。'),C('panel.s3','控制板；仪表盘','The technician reset the alarm using the control panel beside the laboratory entrance.','技术员使用实验室入口旁的控制面板重置了警报。','The technician reset the alarm / using the control panel / beside the laboratory entrance.','panel 还可指带开关或仪表、用来控制机器的板。','面板上的控制装置用于重置警报。'),C('panel.s4','用嵌板覆盖','The builders panelled the reception wall with oak before installing the lights.','安装灯具前，建筑工人用橡木嵌板覆盖了接待室墙面。','The builders panelled the reception wall with oak / before installing the lights.','panel 作动词表示用嵌板覆盖墙面或其他表面。','墙面被橡木板覆盖。')],M('The builders panelled the reception wall by removing every board and leaving bare plaster exposed.','The builders panelled the reception wall by covering it with oak boards.','去掉板材露出墙面不是用嵌板覆盖。','meaning'),[q('What did the carpenter replace?','a wooden section in the classroom door','a group of climate scientists','a laboratory alarm control','木匠更换了门上的木嵌板。'),q('Who answered questions after the lecture?','a group of climate scientists','the carpenters installing oak','the technician resetting the alarm','专家小组回答了学生的问题。',2,'context'),q('What did the technician use to reset the alarm?','the control panel','a door panel','a public panel of scientists','技术员用控制面板重置警报。',3,'context'),q('What did the builders do to the wall?','covered it with oak panels','removed every board from it','asked a panel to answer questions','panel 作动词表示给墙面覆盖嵌板。',4,'meaning')]);
P('pang','Pang is of uncertain origin; it names a sudden sharp pain or a sudden strong feeling such as guilt or regret.',[C('pang.s1','（一阵）剧痛','A sudden pang shot through her ankle when she stepped onto the uneven rock.','她踩上不平的岩石时，脚踝突然一阵剧痛。','A sudden pang shot through her ankle / when she stepped / onto the uneven rock.','pang 可指突然袭来的尖锐身体疼痛。','疼痛随踩到石头而突然出现。'),C('pang.s2','一阵难受','He felt a pang of guilt after realizing that his careless comment had embarrassed his friend.','意识到自己随口的评论让朋友难堪后，他感到一阵内疚。','He felt a pang of guilt / after realizing his careless comment / had embarrassed his friend.','pang 也可指突然涌起的内疚、遗憾等强烈情绪。','朋友受窘引发一阵内疚。')],M('He felt a pang of guilt after he realized his comment had hurt his friend, but the report said he felt no sudden emotion at all.','He felt a pang of guilt when he realized his comment had embarrassed his friend.','pang of guilt 指突然出现的强烈内疚，不能说完全没有情绪。','meaning'),[q('What caused the ankle pang?','stepping on uneven rock','hearing about a pamphlet','seeing a panda eat bamboo','踩上不平的岩石时脚踝突然疼痛。'),q('What caused the pang of guilt?','his comment embarrassed his friend','his friend painted a palette','the station announced a pandemic','他意识到评论让朋友难堪后感到内疚。',2,'context'),q('Which sentence uses pang for physical pain?','A pang struck her side during the run.','A pang of regret followed the decision.','The panel answered questions.','第一句的 pang 指身体突然疼痛。',1,'meaning'),q('Which feeling can be described as a pang?','a sudden wave of regret','a long period of quiet satisfaction','a group of expert advisers','pang 可形容突然涌起的遗憾。',2,'meaning')]);
P('pangaea','Pangaea was coined from Greek pan, “all,” and Gaia, “Earth,” for the supercontinent that joined nearly all land.',C('pangaea.s1','盘古大陆','Fossil matches on widely separated continents helped geologists reconstruct Pangaea before it broke apart.','相距遥远的大陆上发现的相似化石，帮助地质学家重建了盘古大陆分裂前的样貌。','Fossil matches on widely separated continents / helped geologists reconstruct Pangaea / before it broke apart.','Pangaea 是古生代晚期至中生代早期曾存在的超大陆名称。','不同大陆的相似化石支持曾经连成一片的解释。'),M('The geologist reconstructed Pangaea as a supercontinent that never joined any of Earth’s landmasses.','The geologist reconstructed Pangaea as the supercontinent in which Earth’s major landmasses were joined.','Pangaea 指曾把主要陆地连在一起的超大陆；“从未连接”与该义相反。','meaning'),[q('What evidence helped reconstruct Pangaea?','matching fossils on distant continents','identical modern coastlines everywhere','a map of one small island','相距遥远大陆上的相似化石提供了线索。'),q('What was Pangaea?','an ancient supercontinent','a present-day ocean current','a type of fossil itself','Pangaea 是古代超大陆。',1,'meaning'),q('What happened to Pangaea?','it later broke apart','it became a single modern island','it was built by geologists','超大陆后来分裂了。',1,'context'),q('Which word element in Pangaea means “all”?','pan-','-gaea','-logy','pan- 来自希腊语，表示“全部”。',1,'word-formation')]);
P('panhandle','Panhandle combines pan and handle: a projecting strip shaped like a pan handle; as a verb it means to beg in public.',[C('panhandle.s1','锅柄状地区','The narrow panhandle of the state stretches north between two neighboring states.','该州狭长的锅柄状地带向北延伸，夹在两个邻州之间。','The narrow panhandle of the state / stretches north / between two neighboring states.','地理义的 panhandle 指从主体伸出的狭长地带，形状像锅柄。','狭长地带从州的主体伸出。'),C('panhandle.s2','在街头乞讨','A volunteer asked the city to provide shelter so no one would have to panhandle outside the station.','一名志愿者请求市政府提供住所，让人们不必在车站外乞讨。','A volunteer asked the city to provide shelter / so no one would have to panhandle / outside the station.','panhandle 作动词表示在公共场所向陌生人乞讨。','语境中的公共地点和募求钱财表明是乞讨义。')],M('The state’s panhandle was a broad circular region surrounded on every side by the rest of the state.','The state’s panhandle was a long, narrow projection extending from the rest of the state.','panhandle 的地理义是狭长伸出部分，不是圆形区域。','meaning'),[q('What shape did the state panhandle have?','a narrow strip projecting from the state','a circle enclosed by the state','a chain of islands offshore','州的 panhandle 是狭长伸出的地带。',1,'meaning'),q('Why did the volunteer contact the city?','to find shelter so people would not need to beg outside','to ask for a longer handle on a cooking pan','to close the station to travelers','志愿者希望提供住所，减少街头乞讨。',2,'context'),q('What does panhandle mean as a verb?','ask strangers for money in a public place','draw a narrow border on a map','carry a pan by its handle','动词 panhandle 指在公共场所乞讨。',2,'meaning'),q('Which phrase best describes a geographic panhandle?','a long narrow extension of a state','a wide round lake in a state','the central capital district','地理义强调从州主体伸出的狭长部分。',1,'context')]);
P('panic','Panic comes through Latin from Greek panikos, “of Pan”; ancient belief linked the god Pan with sudden, groundless terror.',[C('panic.s1','恐慌；惊慌','A brief panic spread through the crowd when the fire alarm sounded, but the exits stayed clear.','火警响起时，人群短暂地陷入恐慌，但出口仍然畅通。','A brief panic spread through the crowd / when the fire alarm sounded / but the exits stayed clear.','panic 作名词指突然强烈的恐惧，常使人失去冷静。','警报引发短暂恐慌。'),C('panic.s2','（使）恐慌；（使）惊慌失措','The pilot did not panic when one warning light appeared; she followed the checklist calmly.','一盏警示灯亮起时，飞行员没有慌乱，而是镇定地按检查单操作。','The pilot did not panic / when one warning light appeared / she followed the checklist calmly.','panic 作动词可指突然感到恐惧或使人恐慌。','飞行员在警示灯亮起时保持冷静。')],M('When the alarm rang, the passengers panicked by calmly following the safety instructions and keeping the aisle clear.','When the alarm rang, the passengers panicked and rushed toward the exit without checking the instructions.','panic 指突然恐慌；镇定遵循安全指引不是惊慌失措。','meaning'),[q('What triggered the crowd’s brief panic?','the fire alarm','a delayed train announcement','a missing museum pamphlet','火警响起后人群短暂恐慌。'),q('How did the pilot respond to the warning light?','she stayed calm and followed the checklist','she shouted and abandoned the controls','she ignored every instrument permanently','她没有慌乱，而是按检查单操作。',2,'context'),q('Which behavior best shows panic?','people rush without thinking after a sudden threat','people calmly compare several safe routes','a crowd waits quietly for an announcement','panic 常使人因恐惧而不假思索地行动。',1,'meaning'),q('What is the historical association in the word panic?','Greek Pan was believed to inspire sudden terror','a Latin word for a cooking pan','a Greek term for a map of a state','词源关联希腊神祇 Pan 与突发恐惧。',1,'word-formation')]);
P('panorama','Panorama was coined from pan-, “all,” and Greek horama, “sight”; it first named an artwork offering a complete view.',[C('panorama.s1','全景；远景','From the observatory, the panorama included the river, old town, and mountains beyond it.','从天文台望去，眼前的全景包括河流、旧城区和远处的山脉。','From the observatory / the panorama included the river / old town and mountains beyond it.','panorama 指从高处或有利位置看到的宽阔景象。','多个远近地标同时进入视野。'),C('panorama.s2','概述；全面的介绍','The report gives a panorama of urban housing, comparing costs, supply, and regional policy.','报告全面概述了城市住房问题，比较了成本、供应和地区政策。','The report gives a panorama of urban housing / comparing costs, supply / and regional policy.','panorama 也可比喻对某一主题各方面的概览。','报告覆盖住房问题的多个方面。')],M('The guide promised a panorama of the valley but showed visitors only a close-up of one leaf.','The guide promised a panorama of the valley and showed visitors a wide view across it.','全景要呈现广阔景象，单片叶子的特写并非 panorama。','meaning'),[q('What could visitors see from the observatory?','the river, old town, and distant mountains','only a close-up of a leaf','the inside of a closed museum','天文台能看到河流、旧城区和远山的全景。'),q('What does the housing report provide?','a broad survey of several housing issues','a list of one building’s paint colors','a close-up photograph of a window','报告概述了住房的成本、供应和政策等方面。',2,'context'),q('Which view is a panorama?','a wide sweep of a coastline from a cliff','one pebble examined under a lens','a single room viewed through a keyhole','panorama 是宽阔的整体视野。',1,'meaning'),q('What does panorama literally combine?','all and sight','earth and water','fear and breath','pan- 表“全部”，horama 表“景象”。',1,'word-formation')]);
P('pant','Pant may come through Old French pantaisier, perhaps from a Greek word for having visions; it means breathe rapidly or a short gasp.',[C('pant.s1','喘气；喘息','The dog began to pant in the summer heat, so Mara moved its water bowl into the shade.','狗在夏日高温中开始喘气，于是玛拉把水碗移到了阴凉处。','The dog began to pant / in the summer heat / so Mara moved its water bowl into the shade.','pant 作动词指因热、用力或兴奋而急促呼吸。','炎热使狗急促喘气。'),C('pant.s2','气喘吁吁地说','“Wait for me,” he panted as he reached the top of the hill.','他气喘吁吁地爬到山顶时说：“等等我。”','“Wait for me,” he panted / as he reached / the top of the hill.','pant 可接说出的内容，表示说话时仍在喘气。','短语和爬坡语境体现喘着气说话。'),C('pant.s3','喘息；一口急气','After the sprint, she took one deep pant and then slowed her breathing.','冲刺后，她急促地喘了一口气，随后慢慢调整呼吸。','After the sprint / she took one deep pant / and then slowed her breathing.','pant 作名词可指一次短促而急的呼吸。','one 修饰的是一口急促呼吸。')],M('After the steep climb, the runner panted by breathing slowly and evenly without any effort.','After the steep climb, the runner panted and drew quick, short breaths.','pant 描述急促呼吸，不是毫不费力的缓慢均匀呼吸。','meaning'),[q('Why did the dog pant?','the summer heat','a cold bath','a quiet nap indoors','狗在夏日高温中喘气。',1,'context'),q('How did the man deliver “Wait for me”?','while breathing hard near the hilltop','in a calm whisper before the climb','by writing it on a map','他气喘吁吁地说出这句话。',2,'context'),q('What is one pant in the final sentence?','one short, quick breath','a pair of trousers','a complete panorama','pant 作名词可指一口短促急气。',3,'meaning'),q('Which situation most naturally makes a person pant?','running up a steep hill','sitting quietly in a cool room','reading a short note at a desk','剧烈运动后会急促喘气。',1,'usage')]);
P('pantheism','Pantheism combines pan-, “all,” and theism; the term describes the view that God and the universe are identical.',C('pantheism.s1','泛神论','In her lecture on pantheism, the philosopher explained why some thinkers identify the divine with the whole universe.','在泛神论讲座中，哲学家解释了为何一些思想家把神性与整个宇宙视为一体。','In her lecture on pantheism / the philosopher explained / why some thinkers identify the divine with the whole universe.','pantheism 是一种认为神与宇宙同一或万物皆具神性的哲学观点。','讲座明确讨论神性与整个宇宙的关系。'),M('The lecture defined pantheism as the belief that God is wholly separate from the universe and unrelated to nature.','The lecture defined pantheism as the belief that God and the universe are identical or that the divine is present in all things.','泛神论将神与宇宙联系为一体；“完全分离”与定义相反。','meaning'),[q('What did the lecture examine?','the view that the divine is identified with the universe','the claim that nature has no relation to any divine reality','the history of mountain panoramas','讲座讨论神性与宇宙一体的观点。'),q('Which belief is most closely associated with pantheism?','the universe as a whole is divine','a single local spirit controls the weather','the divine is entirely unrelated to existence','泛神论将神性与宇宙整体联系起来。',1,'meaning'),q('What does the element pan- contribute to pantheism?','the idea of all or everything','the idea of a short breath','the idea of a narrow state border','pan- 在该词中表示“全部”。',1,'word-formation'),q('Which topic belongs in a lecture on pantheism?','whether God and the universe are identical','how to repair a paperclip','how a state acquired its panhandle','泛神论讨论神与宇宙是否同一。',1,'context')]);
P('pantomime','Pantomime comes from Greek pantomimos, “imitator of all”; it names mime performance and, in Britain, a traditional comic holiday show.',[C('pantomime.s1','哑剧；圣诞童话剧','The children watched a pantomime in which the actors used gestures, songs, and comic characters to tell the story.','孩子们观看了一场哑剧式童话剧，演员用手势、歌曲和滑稽角色讲故事。','The children watched a pantomime / in which the actors used gestures, songs / and comic characters to tell the story.','pantomime 可指主要靠动作表达的表演，也可指英国传统的节庆喜剧演出。','演员以手势和滑稽表演推进故事。'),C('pantomime.s2','打手势表达','Without speaking, Niko pantomimed opening an umbrella to show the class what he had forgotten.','尼科没有说话，而是用动作比划打开雨伞，告诉全班他忘了什么。','Without speaking / Niko pantomimed opening an umbrella / to show the class what he had forgotten.','pantomime 作动词表示不说话而用动作或手势表达。','opening an umbrella 是他比划出来的动作。')],M('The actor pantomimed the locked door by describing it aloud in a long speech and making no gestures.','The actor pantomimed the locked door by silently acting out how it opened.','pantomime 作动词强调用动作表达，不是只用长篇口述。','usage'),[q('How did the actors tell the story?','with gestures, songs, and comic characters','with a silent written report only','with a map of a state border','表演结合手势、歌曲和喜剧角色。'),q('How did Niko show what he had forgotten?','he acted out opening an umbrella without speaking','he drew a panorama of the classroom','he asked the class to read a pamphlet','他不说话，用动作比划打开雨伞。',2,'context'),q('What does pantomime mean as a verb?','communicate by acting or gesturing','write a formal philosophical definition','walk in a narrow procession','动词 pantomime 表示用动作或手势表达。',2,'meaning'),q('Which feature is central to a mime pantomime?','meaning is conveyed through visible action','every character must remain off stage','the plot is explained only in footnotes','哑剧主要通过可见动作传达内容。',1,'meaning')]);
P('pantomimic','Pantomimic is built from pantomime and -ic, meaning “of or like pantomime,” especially expressive through gestures.',C('pantomimic.s1','哑剧式的；用手势表达的','Her pantomimic shrug made it clear that she had no idea where the missing key had gone.','她用哑剧式的耸肩动作清楚表示，她不知道丢失的钥匙去了哪里。','Her pantomimic shrug / made it clear / that she had no idea where the missing key had gone.','pantomimic 是形容词，形容类似哑剧、靠动作表达的方式。','shrug 是可视动作，没有语言说明。'),M('The actor gave a pantomimic explanation by reading every sentence aloud from a prepared speech.','The actor gave a pantomimic explanation by silently acting out the steps with gestures.','pantomimic 描述用动作表达；照稿朗读是言语表达。','meaning'),[q('What did the shrug communicate?','she did not know where the key was','she had found the key in her pocket','she wanted to perform a song','耸肩用动作表达了她不知道钥匙在哪。'),q('What makes an explanation pantomimic?','it relies on gestures or acted movements','it consists only of printed footnotes','it uses a formal scientific equation','pantomimic 强调用手势或动作表达。',1,'meaning'),q('Which scene is pantomimic?','an actor silently mimes opening a heavy door','a speaker reads a paragraph into a microphone','a scientist labels a fossil collection','无声比划开门是哑剧式动作。',1,'context'),q('What is the suffix -ic doing in pantomimic?','forming an adjective meaning related to pantomime','forming a verb meaning to ask for money','forming a noun meaning a stage curtain','-ic 把 pantomime 相关含义构成形容词。',1,'word-formation')]);
P('pants','Pants is a shortened form of pantaloons; regional usage differs: American English usually means trousers, British English usually underwear.',[C('pants.s1','（美式）长裤；裤子','In American English, Lena packed two pairs of pants and a warm sweater for the trip.','在美式英语中，莉娜为旅行装了两条长裤和一件暖和的毛衣。','In American English / Lena packed two pairs of pants / and a warm sweater for the trip.','美式英语里 pants 通常指覆盖双腿的长裤。','和毛衣一起打包的衣物语境指长裤。'),C('pants.s2','（英式）内裤','In British English, he changed into clean pants after swimming and put his trousers back on.','在英式英语中，他游泳后换上干净的内裤，再穿回长裤。','In British English / he changed into clean pants after swimming / and put his trousers back on.','英式英语里 pants 通常指贴身内裤；trousers 才是长裤。','pants 与随后穿回的 trousers 区分开。'),C('pants.s3','（英式口语）很差劲；毫无价值','The reviewer said the sequel was pants because its plot copied the first film without adding anything.','评论者说续集糟透了，因为情节照搬第一部，没有任何新意。','The reviewer said the sequel was pants / because its plot copied the first film / without adding anything.','英式非正式用法中，pants 可形容某事很差劲或毫无价值。','评论者在评价电影质量。')],M('In American English, Lena packed pants as underwear and trousers as a separate second garment.','In American English, Lena packed pants as trousers; in British English, pants commonly means underwear.','该句把英美常见义混在一起；美式 pants 通常就是长裤。','usage'),[q('In the American-English sentence, what did Lena pack?','two pairs of trousers','two pairs of underwear','two pairs of gloves','美式 pants 指长裤。',1,'context'),q('What did he change into after swimming in the British-English example?','clean underwear','a second pair of trousers','a dry sweater','该英式例句中的 pants 指内裤。',2,'context'),q('What does “the sequel was pants” mean in informal British English?','the sequel was very bad','the sequel was a pair of trousers','the sequel was released in spring','这里 pants 是“很差劲”的口语形容词。',3,'meaning'),q('Why should a speaker check the regional context for pants?','American and British English commonly assign it different clothing meanings','the word has no clothing meaning in either variety','the word can only describe a movie','美式多指长裤，英式通常指内裤。',1,'usage')]);
P('papa','Papa is a familiar child word for father; it appears in many languages, and its precise borrowing history varies.',C('papa.s1','爸爸','After the long train ride, the toddler ran to her papa and reached up to be carried.','长途火车旅行结束后，小女孩跑向爸爸，伸手要他抱。','After the long train ride / the toddler ran to her papa / and reached up to be carried.','papa 是亲昵、家庭化的“爸爸”称呼，常由幼儿或家人使用。','幼儿跑向家长并要抱抱。'),M('The toddler called her papa, but she was asking for a stranger with no family relationship to her.','The toddler called her papa, meaning her father, and asked him to carry her.','papa 指父亲或熟悉的父亲称呼，不是陌生人。','meaning'),[q('Who did the toddler run to?','her father','the train conductor','a museum guide','她跑向爸爸。'),q('What did she do after reaching her papa?','raised her arms to be carried','handed him a map of the state','asked him to pantomime a song','她伸手要爸爸抱。'),q('Which speaker is most likely to use papa?','a young child addressing her father','a geologist naming an ancient continent','a pilot describing a warning light','papa 常见于幼儿对父亲的称呼。',1,'usage'),q('What does the entry say about papa’s history?','it is a familiar child word with varied language histories','it has one certain path from a single Latin verb','it was coined as the name of a stage play','该词常见于多种语言，具体借词路径不一。',1,'word-formation')]);
P('paper','Paper comes through French from Latin papyrus, ultimately the name of the Egyptian reed; it can mean material, a newspaper, an essay, documents, or cover a wall.',[C('paper.s1','纸；纸张','The archivist placed the fragile letter between two sheets of acid-free paper.','档案员把易碎的信件夹在两张无酸纸之间。','The archivist placed the fragile letter / between two sheets / of acid-free paper.','paper 作名词可指用于书写、印刷或包装的薄片材料。','信件被夹在两张纸之间。'),C('paper.s2','报纸','The local paper reported that the old bridge would reopen after repairs.','当地报纸报道，老桥维修后将重新开放。','The local paper reported / that the old bridge would reopen / after repairs.','paper 可用作 newspaper 的简称，指报纸或新闻机构。','它报道地方新闻。'),C('paper.s3','论文；文章；试卷','Mira submitted a paper on coastal erosion before the history seminar began.','历史研讨课开始前，米拉提交了一篇关于海岸侵蚀的论文。','Mira submitted a paper on coastal erosion / before the history seminar began.','paper 可指学术论文、文章，或考试试卷。','提交给研讨课的写作作品是一篇论文。'),C('paper.s4','文件；证件','The customs officer checked the traveler’s papers before allowing her to leave the terminal.','海关官员核查了旅客的证件后，才允许她离开航站楼。','The customs officer checked the traveler’s papers / before allowing her to leave / the terminal.','复数 papers 可指证明身份或权利的正式文件。','官员核对正式证件。'),C('paper.s5','用纸或墙纸覆盖','The decorators papered the hallway in pale blue before moving the furniture back.','装饰工人先用浅蓝色墙纸糊好走廊，随后才把家具搬回。','The decorators papered the hallway in pale blue / before moving the furniture back.','paper 作动词可表示用纸或墙纸覆盖墙面。','墙面被贴上浅蓝色墙纸。')],M('Mira submitted a paper on coastal erosion, but the instructor said she had submitted no written work at all.','Mira submitted a paper on coastal erosion, a written essay for the seminar.','paper 在该句指已提交的论文；说没有任何书面作品与事实相反。','meaning'),[q('What protected the fragile letter?','two sheets of acid-free paper','a cotton blanket','a glass panel from a greenhouse','信件夹在两张无酸纸之间。',1,'context'),q('What did the local paper report?','the bridge would reopen after repairs','the town had discovered Pangaea','the seminar had been canceled forever','报纸报道桥梁维修后将重新开放。',2,'context'),q('What did Mira submit?','an academic essay on coastal erosion','an official passport','a roll of hallway wallpaper','研讨课论文属于 paper 的文章义。',3,'context'),q('What did the decorators do when they papered the hallway?','covered its wall with wallpaper','checked the traveler’s documents','printed a local newspaper','paper 作动词表示用墙纸覆盖墙面。',5,'meaning')]);
P('paperback','Paperback combines paper and back; as a noun it is a book with a flexible paper cover, and as an adjective it describes that binding.',[C('paperback.s1','平装书','She bought the paperback because it was light enough to carry on the long bus ride.','她买了这本平装书，因为它很轻，适合在漫长的公交车程中携带。','She bought the paperback / because it was light enough / to carry on the long bus ride.','paperback 作名词指纸质软封面的书，与 hardcover 相对。','轻便的封面装订适合携带。'),C('paperback.s2','平装的','The publisher released a paperback edition of the novel six months after the hardcover version.','出版社在精装版出版六个月后推出了这部小说的平装版。','The publisher released a paperback edition / of the novel / six months after the hardcover version.','paperback 作定语时表示采用柔软纸质封面的装订形式。','它修饰 edition，与精装版对照。')],M('She chose the paperback because it had a rigid cloth-covered board binding and weighed more than the hardcover.','She chose the paperback because its flexible paper cover made it lighter than the hardcover.','paperback 指软纸封面装订，刚硬布面封装是精装书的特征。','meaning'),[q('Why did she choose the paperback?','it was light to carry on the bus','it had a metal cover','it contained the route map','她选择平装本是因为轻便。'),q('What appeared six months after the hardcover?','a paperback edition','a new bus line','a revised dictionary entry','出版社后来推出了平装版。',2,'context'),q('Which book is a paperback?','a novel with a flexible paper cover','a novel bound in a rigid cloth-covered board','a manuscript printed on loose cards only','平装书使用柔软纸质封面。',1,'meaning'),q('In “paperback edition,” what does paperback describe?','the book’s binding style','the author’s nationality','the story’s point of view','paperback 在此形容装订形式。',2,'usage')]);
P('paperclip','Paperclip is a transparent compound of paper and clip, naming the small bent-wire fastener used to hold sheets together.',C('paperclip.s1','曲别针','Rina used a paperclip to keep the signed forms together without punching holes in them.','莉娜用曲别针把签过字的表格夹在一起，没有在纸上打孔。','Rina used a paperclip / to keep the signed forms together / without punching holes in them.','paperclip 指弯曲的金属夹，用来夹住纸张。','它固定文件而不打孔。'),M('Rina used a paperclip to bind the signed forms by punching permanent holes through every sheet.','Rina used a paperclip to hold the signed forms together without punching holes.','曲别针夹住纸张而不打孔；打孔装订是另一种方法。','usage'),[q('What did Rina use to keep the forms together?','a paperclip','a bottle of ink','a strip of wallpaper','她用曲别针夹住表格。'),q('What did the paperclip avoid doing to the sheets?','punching holes in them','printing a newspaper on them','folding them into a panorama','曲别针无需在纸上打孔。'),q('Which object is a paperclip?','a bent wire fastener for sheets','a flexible cover around a book','a reed used to make ancient writing material','paperclip 是夹纸用的弯曲金属夹。',1,'meaning'),q('How is paperclip formed?','by combining paper and clip','by shortening pantaloons','by joining pan and Gaia','这个复合词由 paper 和 clip 组成。',1,'word-formation')]);
P('papyrus','Papyrus comes from Latin papyrus and Greek papuros, the name of the Nile reed and the writing material made from its strips.',C('papyrus.s1','纸莎草；纸莎草纸','The museum displayed a papyrus fragment covered with lines of writing from ancient Egypt.','博物馆展出了一片写有古埃及文字的纸莎草纸残片。','The museum displayed a papyrus fragment / covered with lines of writing / from ancient Egypt.','papyrus 可指尼罗河流域的纸莎草植物，也可指用其茎片制成的古代书写材料。','有文字的古代残片指纸莎草纸。'),M('The curator identified the inscribed papyrus as a modern sheet of plastic made from petroleum.','The curator identified the inscribed papyrus as ancient writing material made from strips of the Nile reed.','papyrus 的材料义指由纸莎草茎片制成的古代书写材料，不是现代塑料。','meaning'),[q('What was written on the museum fragment?','lines of ancient Egyptian writing','a modern printed newspaper','a map of the state panhandle','展品是有古埃及文字的纸莎草纸残片。'),q('What does papyrus name besides the writing material?','the Nile reed used to make it','a kind of flexible book cover','a metal clip for pages','papyrus 也指用于制纸的尼罗河植物。'),q('Which item is most likely made of papyrus?','an ancient manuscript sheet made from reed strips','a modern plastic document folder','a wire fastener for papers','古代莎草纸由植物茎片制成。',1,'meaning'),q('Which languages supplied the name papyrus?','Greek papuros through Latin papyrus','Old English panne through French','Italian Pantalone through Spanish','英语词经拉丁语承自希腊语 papuros。',1,'word-formation')]);
P('par','Par comes from Latin par, “equal”; it names the usual standard and, in golf or finance, a defined expected or face value.',[C('par.s1','一般水平；同等','The renovated library is now on a par with the newest public buildings in the region.','翻新后的图书馆如今已达到本地区最新公共建筑的水平。','The renovated library / is now on a par with / the newest public buildings in the region.','on a par with 表示与某人或某物处于同等水平。','图书馆的质量与新建筑相当。'),C('par.s2','标准杆；票面价值','The golfer finished the hole in four strokes, exactly matching its par of four.','这位高尔夫球手用四杆完成该洞，正好达到该洞的标准杆数四杆。','The golfer finished the hole in four strokes / exactly matching / its par of four.','高尔夫中的 par 是完成一洞或一轮的预期杆数；金融中还可指票面价值。','实际用杆数与预期数相同。')],M('The hole had a par of four, but the golfer was praised for finishing it in only one hundred strokes.','The hole had a par of four, and the golfer matched it by finishing in four strokes.','par 是预期杆数；一百杆并不等于四杆标准。','meaning'),[q('What does “on a par with” mean in the library example?','at the same standard as','far below the quality of','located beside the entrance to','图书馆达到与新建筑相同的水平。',1,'usage'),q('How many strokes was par for the golf hole?','four','one','one hundred','该洞的标准杆数是四杆。',2,'context'),q('When does a golfer make par on this hole?','when the golfer completes it in four strokes','when the golfer loses the scorecard','when the golfer takes twice as many strokes','用预期杆数四杆完成即达到标准杆。',2,'meaning'),q('What is the common Latin source meaning of par?','equal','paper','fear','拉丁语 par 表示“相等”。',1,'word-formation')]);
P('parable','Parable comes through Old French and Latin from Greek parabole, “comparison”; it is a short story that teaches a moral lesson.',C('parable.s1','寓言','The teacher used a parable about a lost coin to help the class discuss patience and compassion.','老师用一则关于丢失硬币的寓言，引导全班讨论耐心与同情心。','The teacher used a parable / about a lost coin / to help the class discuss patience and compassion.','parable 是借具体故事表达道德或宗教教训的短篇故事。','故事被用来讨论抽象品格。'),M('The teacher called the story a parable, although it contained no lesson or point beyond a list of coin prices.','The teacher called the story a parable because it used a brief narrative to teach a moral lesson.','寓言要借故事传达教训；纯价格清单不是寓言。','meaning'),[q('What did the lost-coin parable help the class discuss?','patience and compassion','how to repair a motorcycle','the geology of a supercontinent','寓言引导学生讨论耐心与同情心。'),q('What makes a story a parable?','it uses a brief narrative to teach a lesson','it lists facts without a point','it records every event in a person’s life','parable 通过短故事传达道理。',1,'meaning'),q('Which story is most likely a parable?','a short tale about a generous traveler that teaches kindness','a timetable listing train departures','a description of a paperclip’s dimensions','借旅人故事教人友善的短篇故事符合寓言。',1,'context'),q('Why is “comparison” relevant to the Greek source of parable?','a parable presents an idea through a comparable story','a parable measures a golf hole’s strokes','a parable names a reed plant','词源中的“比较”对应以故事说明道理。',1,'word-formation')]);
P('parabola','Parabola comes through Latin from Greek parabole, “comparison”; in mathematics it names a conic curve defined by a focus and directrix.',C('parabola.s1','抛物线','The graph formed a parabola, with each point equally distant from the focus and the directrix.','图像形成一条抛物线，曲线上每一点到焦点和准线的距离相等。','The graph formed a parabola / with each point equally distant / from the focus and the directrix.','parabola 是平面上按焦点与准线定义的圆锥曲线。','句子描述其焦点—准线定义。'),M('The student labeled a parabola as a straight line whose points all stay the same distance from one fixed center.','The student labeled the U-shaped conic curve defined by a focus and directrix as a parabola.','题干把抛物线误说成直线且采用圆的中心定义。','meaning'),[q('What two objects define the curve in the example?','a focus and a directrix','a center and a radius','a pan and its handle','抛物线可由焦点和准线定义。'),q('Which shape is a parabola?','a U-shaped conic curve','a circle with one fixed center','a straight segment with two endpoints','抛物线是特定的圆锥曲线，常呈U形。',1,'meaning'),q('What was the student labeling?','the graph of a conic curve','a short moral tale','a golf scorecard','学生标注的是曲线图像。'),q('Which use of parabola is correct?','The satellite dish has a parabolic reflector.','The parable is shaped like a parabola of moral values.','The paperclip is a parabola of metal.','抛物线可用于描述卫星天线的反射面形状。',1,'usage')]);
P('parachute','Parachute comes from French para- “against” plus chute “fall”; it names a canopy that slows descent and the act of descending by one.',[C('parachute.s1','降落伞','The instructor checked each parachute before the students boarded the aircraft for their first jump.','学员们登机进行首次跳伞前，教练检查了每一顶降落伞。','The instructor checked each parachute / before the students boarded the aircraft / for their first jump.','parachute 作名词指在空中张开、减缓下落速度的装置。','登机跳伞前要检查装置。'),C('parachute.s2','跳伞降落；空投','Rescue teams parachuted food and medical kits into the valley after the bridge collapsed.','桥梁坍塌后，救援队把食品和医疗包空投到山谷。','Rescue teams parachuted food and medical kits / into the valley / after the bridge collapsed.','parachute 作动词可指用降落伞空投物资或跳伞降落。','物资被空投进难以抵达的山谷。')],M('The rescue crew parachuted medical kits into the valley by lowering them on a boat through the river.','The rescue crew parachuted medical kits into the valley by dropping them with parachutes from the air.','空投 parachuted 指从空中借助降落伞投送，不是乘船顺流运送。','meaning'),[q('What did the instructor check?','the students’ parachutes','their paperbacks','a map of the state','教练检查了学生的降落伞。'),q('How did rescue teams get supplies into the valley?','they dropped them from the air using parachutes','they carried them over a bridge that had collapsed','they mailed them in a paper envelope','救援队用降落伞空投物资。',2,'context'),q('What does parachute mean as a noun?','a canopy that slows a fall through the air','a device for measuring golf strokes','a short story with a moral','降落伞张开后能减缓下落。',1,'meaning'),q('How is the French compound explained?','para- means against and chute means fall','pan- means all and gaia means earth','paper means reed and clip means cover','词源把 parachute 解释为“抵御下落”。',1,'word-formation')]);
P('parade','Parade came through French from Spanish parada, “a stopping or display”; it names a procession, military inspection, showy display, or marching procession.',[C('parade.s1','游行；庆祝队伍','The spring parade moved slowly down Main Street, with brass bands and decorated floats.','春季游行队伍伴着铜管乐队和装饰花车，缓缓穿过主街。','The spring parade moved slowly down Main Street / with brass bands / and decorated floats.','parade 作名词可指由人群、乐队或车辆组成的公开行进队伍。','乐队与花车在街上列队前行。'),C('parade.s2','阅兵；检阅','The new recruits stood in formation for the morning parade while the commander inspected their uniforms.','新兵们在晨间检阅中列队，指挥官检查他们的制服。','The new recruits stood in formation / for the morning parade / while the commander inspected their uniforms.','military parade 可指军队为仪式或检阅而集合列队。','指挥官检查列队士兵。'),C('parade.s3','炫耀；展示','He paraded his expensive watch at lunch, turning his wrist toward everyone at the table.','午餐时他炫耀昂贵的手表，不停把手腕转向桌边的每个人。','He paraded his expensive watch at lunch / turning his wrist / toward everyone at the table.','parade 作及物动词可表示炫耀性地展示某物。','他有意让所有人看到手表。'),C('parade.s4','列队行进；游行','The band paraded through the town before stopping in the square for the final song.','乐队在镇上列队行进，随后在广场停下演奏最后一首歌。','The band paraded through the town / before stopping in the square / for the final song.','parade 作不及物动词表示成队游行或列队行进。','乐队沿街行进并在广场停下。')],M('The band paraded through town by remaining inside the station and never joining the procession.','The band paraded through town by marching together along the street.','parade through town 表示成队行进；留在车站没有游行。','meaning'),[q('What moved down Main Street in the spring parade?','brass bands and decorated floats','a row of museum shelves','a line of isolated hikers','游行包含铜管乐队和装饰花车。',1,'context'),q('What happened during the military parade?','the commander inspected the recruits’ uniforms','the recruits mailed their papers','the band repaired its instruments','阅兵时指挥官检查新兵制服。',2,'context'),q('What did he do when he paraded his watch?','showed it off conspicuously','hid it under a paperclip','used it to count golf strokes','parade 作动词可表示炫耀性展示。',3,'meaning'),q('How did the band parade through the town?','it marched together along the streets','it stayed inside the station','it moved silently by parachute','乐队列队沿街行进。',4,'meaning')]);
P('paradigm','Paradigm comes through Latin and French from Greek paradeigma, “example or pattern”; it can mean a framework, model, or inflection table.',[C('paradigm.s1','范式；理论框架','The discovery challenged the old paradigm that treated all local species as living in isolated habitats.','这一发现挑战了旧有范式——它把当地所有物种都视为生活在彼此隔离的栖息地中。','The discovery challenged the old paradigm / that treated all local species / as living in isolated habitats.','paradigm 可指某个领域中被广泛接受的思想框架或方法体系。','新证据迫使研究者质疑旧框架。'),C('paradigm.s2','典范；范例','For many volunteers, the clinic is a paradigm of patient-centered community care.','对许多志愿者而言，这家诊所是以患者为中心的社区护理典范。','For many volunteers / the clinic is a paradigm / of patient-centered community care.','paradigm 也可指典型或值得效仿的例子。','诊所被当作优秀护理的范例。'),C('paradigm.s3','词形变化表','The grammar book prints a paradigm of the verb, showing its present, past, and participle forms.','语法书列出该动词的词形变化表，展示现在式、过去式和分词形式。','The grammar book prints a paradigm of the verb / showing its present, past / and participle forms.','语言学中 paradigm 可指展示某词各屈折形式的表格或模式。','列出的不同时态和分词属于词形变化。')],M('The grammar book’s paradigm listed one unchanged form for every tense and omitted all the verb’s inflections.','The grammar book’s paradigm displayed the verb’s different present, past, and participle forms.','词形变化 paradigm 要展示不同形式，不能把所有时态说成同一个不变形式。','meaning'),[q('What did the discovery challenge?','an accepted framework about isolated habitats','the spelling of a local newspaper','the number of strokes on a golf hole','发现挑战了关于栖息地隔离的旧框架。',1,'context'),q('Why is the clinic called a paradigm?','it is treated as a model of good community care','it has no patients or staff','it publishes a table of verb forms','这里 paradigm 指值得效仿的典范。',2,'meaning'),q('What does the grammar book’s paradigm show?','different inflected forms of one verb','a procession through town','the focus and directrix of a curve','词形变化表列出动词不同形式。',3,'context'),q('Which meaning of paradigm fits “a shift in the scientific paradigm”?','a change in a field’s accepted framework','a small flexible book cover','a sudden feeling of terror','科学范式转变指研究领域框架发生变化。',1,'meaning')]);
P('paradise','Paradise came through Old French, Latin, and Greek from an Iranian word for an enclosure or park; senses include heaven, an ideal place, and bliss.',[C('paradise.s1','天堂；天国','In the novel, the weary travelers believe that the just will find peace in paradise after death.','小说中，疲惫的旅人相信善良的人死后会在天堂得到安宁。','In the novel / the weary travelers believe / that the just will find peace in paradise after death.','paradise 可指宗教信仰中善人死后前往的理想居所。','人物谈到死后归宿与永恒安宁。'),C('paradise.s2','乐园；极美好的地方','For the birdwatchers, the quiet marsh with its hundreds of nesting cranes was paradise.','对观鸟者来说，这片有数百只鹤筑巢的宁静湿地简直是乐园。','For the birdwatchers / the quiet marsh with its hundreds of nesting cranes / was paradise.','paradise 也可比喻极其美丽、舒适或令人愉悦的地方。','丰富的鸟类与宁静环境让此地令人向往。'),C('paradise.s3','至福；极乐处境','After months of deadlines, a week with no meetings felt like paradise to the research team.','赶了数月的截止期限后，对研究团队而言，一周没有会议简直是极乐。','After months of deadlines / a week with no meetings / felt like paradise to the research team.','paradise 可指一种极度幸福、舒适的状态。','没有会议让团队获得理想的轻松状态。')],M('The birdwatchers called the polluted, empty marsh paradise because it offered no wildlife and no pleasant surroundings.','The birdwatchers called the peaceful marsh paradise because it offered abundant wildlife and a beautiful setting.','paradise 的比喻义表示美好宜人的地方；污染且荒凉的湿地不符合这里的描述。','meaning'),[q('What do the travelers hope to find after death?','peace in paradise','a new job in the city','a route across the marsh','他们相信善人死后会在天堂安宁。',1,'context'),q('Why is the marsh paradise to birdwatchers?','hundreds of cranes nest in its peaceful setting','it has no birds and is heavily polluted','it contains a busy airport runway','丰富鸟类和宁静环境使湿地成为观鸟乐园。',2,'context'),q('What felt like paradise to the research team?','a week without meetings after months of deadlines','another month of daily emergency meetings','a noisy office with no windows','对团队而言，无会议的一周带来极度轻松。',3,'context'),q('Which meaning fits “a paradise for gardeners”?','an especially pleasant place for gardening','a doctrine about parallel lines','a short story teaching a moral','“园艺爱好者的乐园”使用的是美好之地这一比喻义。',2,'meaning')]);
P('paradox','Paradox came through Latin from Greek paradoxon, “contrary to expectation,” from para-, “contrary,” and doxa, “opinion.”',[C('paradox.s1','悖论；似非而是的说法','“Less is more” sounds like a paradox, yet the designer used fewer features to make the device easier to use.','“少即是多”听来像悖论，但设计师确实通过减少功能让设备更易使用。','“Less is more” sounds like a paradox / yet the designer used fewer features / to make the device easier to use.','paradox 可指表面矛盾或违背常识、却可能揭示真实道理的说法。','减少功能反而改善体验，构成表面矛盾。'),C('paradox.s2','矛盾的人；矛盾的情况','The town is a paradox: it has a modern rail station but no reliable bus service.','这个小镇本身充满矛盾：它有现代化火车站，却没有可靠的公交服务。','The town is a paradox / it has a modern rail station / but no reliable bus service.','paradox 也可指同时具有彼此矛盾特征的人或情况。','现代火车站与缺乏公交并置，形成矛盾情形。')],M('The statement “less is more” is a paradox, but it expresses two ideas that can never be true together and offers no meaningful point.','The statement “less is more” is a paradox because an apparent contradiction expresses a useful truth in the right context.','悖论表面矛盾却可能包含道理；这里的说法用减少来说明简化可以改善体验。','meaning'),[q('Why did fewer device features make the product easier to use?','the design showed how “less is more” can express a useful truth','the design added more controls to every screen','the device became heavier and harder to hold','删减功能反而改善体验，体现了“少即是多”的悖论。',1,'context'),q('What makes the town a paradox?','it has a modern rail station but unreliable buses','it has no station and a perfect bus network','it is both empty and located on a map','现代火车站与缺乏可靠公交构成矛盾反差。',2,'context'),q('Which statement is a paradox?','The more carefully she planned, the more surprises she discovered.','The box is blue and measures ten centimeters wide.','The train arrived at noon after leaving at eleven.','计划越周密却发现越多意外，表面上有矛盾。',1,'meaning'),q('What does Greek doxa contribute to the origin of paradox?','opinion or expectation','a curved mathematical line','a formal line of soldiers','doxa 表示意见，paradox 原指违背常见意见。',1,'word-formation')]);
P('paradoxical','Paradoxical is formed from paradox and -ical; it describes something that appears self-contradictory or conflicts with expectation.',C('paradoxical.s1','自相矛盾似的；出人意料的','It seems paradoxical that adding a short break helped the students finish the exam faster.','增加一次短暂休息反而帮助学生更快完成考试，这看起来似乎自相矛盾。','It seems paradoxical / that adding a short break / helped the students finish the exam faster.','paradoxical 形容表面上矛盾、违背预期但可能成立的情况。','休息通常被看成暂停，却提高了完成速度。'),M('It was paradoxical that the students finished sooner after a break, but the teacher said the result was completely ordinary and expected.','It was paradoxical that the students finished sooner after a break, contrary to what the teacher had expected.','paradoxical 表示违背预期；若结果完全普通且符合预期，就不应这样形容。','meaning'),[q('What seemed paradoxical about the exam?','a short break helped students finish sooner','the exam contained questions printed on paper','students wrote their names at the top','短暂休息反而缩短完成时间，看起来不合预期。'),q('When is a result paradoxical?','when it seems to conflict with expectation','when it exactly follows the expected pattern','when it is written in a paragraph','paradoxical 描述表面上与预期冲突的结果。',1,'meaning'),q('Which situation is paradoxical?','a noisier room helps a team concentrate better','a quiet room remains quiet','a clock shows the time it was set to show','更吵的环境反而帮助专注，构成意外反差。',1,'context'),q('What is the relation between paradoxical and paradox?','paradoxical is an adjective formed from paradox','paradoxical is the plural noun of paradox','paradoxical names a curved graph','paradoxical 是由 paradox 构成的形容词。',1,'word-formation')]);
P('paradoxically','Paradoxically is the adverb from paradoxical, used to introduce a surprising fact that conflicts with expectation.',C('paradoxically.s1','矛盾的是；出人意料的是','Paradoxically, the cheaper insulation saved the building more energy because it was installed throughout the roof.','矛盾的是，价格较低的隔热材料因覆盖了整个屋顶，反而为建筑节省了更多能源。','Paradoxically / the cheaper insulation saved the building more energy / because it was installed throughout the roof.','paradoxically 常置于句首，提示后面的事实出乎意料或表面矛盾。','成本更低却节省更多能源，与常见预期相反。'),M('Paradoxically, the cheaper insulation saved more energy, and the report said this result was exactly what engineers had predicted.','Paradoxically, the cheaper insulation saved more energy, contrary to the engineers’ prediction.','若结果完全符合预测，就不宜用 paradoxically 引出意外。','usage'),[q('What unexpected result did the insulation produce?','the cheaper material saved more energy','the roof became smaller','the building lost all its windows','低价材料因覆盖整个屋顶而节省了更多能源。'),q('What does paradoxically signal at the start of a sentence?','the following fact conflicts with expectation','the following sentence gives a simple list','the speaker is asking for a definition','句首 paradoxically 提示后面是意外或表面矛盾的事实。',1,'usage'),q('Which sentence uses paradoxically appropriately?','Paradoxically, the stricter rule led to fewer inspections.','Paradoxically, the sun rose in the east as expected.','Paradoxically, the report contained three paragraphs.','严格规则反而减少检查次数，结果出乎预期。',1,'context'),q('Which form is paradoxically?','an adverb derived from paradoxical','a noun meaning a type of curve','a plural form of paradise','paradoxically 是 paradoxical 的副词形式。',1,'word-formation')]);
P('paragon','Paragon came through Italian paragone, “touchstone for testing gold,” and French; it now means a model of excellence.',C('paragon.s1','典范；完美榜样','The relief worker was a paragon of patience, listening carefully to every family before arranging aid.','这位救援工作者堪称耐心的典范，她为每个家庭安排援助前都会认真倾听。','The relief worker was a paragon of patience / listening carefully to every family / before arranging aid.','paragon 指某种优点或品质的杰出典范。','她一贯耐心对待每个家庭。'),M('The panel called him a paragon of honesty even though he had deliberately falsified every account.','The panel called him a paragon of honesty because he had consistently reported every account truthfully.','paragon 是美德的典范；蓄意伪造账目与诚实相反。','meaning'),[q('What quality made the relief worker a paragon?','patience with every family','speed in avoiding all conversations','skill at hiding the aid supplies','她认真倾听每个家庭，体现耐心。'),q('What did the panel praise about the honest paragon?','truthful reporting','deliberate falsification','refusal to check any records','诚实典范会如实报告。'),q('Which person could be called a paragon of courage?','a firefighter who enters a burning home to rescue a child','a person who abandons every task when it becomes difficult','a clerk who refuses to open the office','冒险救人的消防员可作为勇气典范。',1,'meaning'),q('What did Italian paragone first refer to?','a touchstone used to test gold','a short story about a lost coin','a line that never meets another','paragone 最初指用于检验黄金的试金石。',1,'word-formation')]);
P('paragraph','Paragraph came through French and Latin from Greek paragraphos, “written beside”; it names a section of prose and the act of dividing text into sections.',[C('paragraph.s1','（文章的）段；段落','The second paragraph explains why the bridge needs a stronger foundation.','第二段解释了这座桥为何需要更坚固的地基。','The second paragraph explains / why the bridge needs / a stronger foundation.','paragraph 作名词指围绕一个主题组织起来、通常另起一行的文字部分。','第二段集中解释一个原因。'),C('paragraph.s2','分成段落','The editor asked Jo to paragraph the long speech so readers could follow each change of topic.','编辑请乔把这篇长演讲分成段落，以便读者跟上每次主题转换。','The editor asked Jo to paragraph the long speech / so readers could follow / each change of topic.','paragraph 作动词表示把文本划分成段落。','划分段落帮助标出主题变化。')],M('The editor asked Jo to paragraph the speech by removing every line break and combining all topics into one block.','The editor asked Jo to paragraph the speech by separating its changes of topic into clear blocks.','paragraph 作动词是划分段落；合并所有主题会抹去段落界线。','meaning'),[q('What did the second paragraph explain?','why the bridge needs a stronger foundation','how the relief worker arranged aid','why the graph forms a parabola','第二段解释桥梁需要更坚固地基的原因。',1,'context'),q('Why did the editor ask Jo to paragraph the speech?','to mark topic changes for readers','to turn it into a single unbroken block','to remove its meaning from the text','分段可帮助读者辨认主题转换。',2,'context'),q('What is a paragraph in an essay?','a group of sentences developing one idea','a single punctuation mark','a list of unrelated page numbers','段落通常围绕一个中心意思展开。',1,'meaning'),q('Which sentence uses paragraph as a verb?','Please paragraph the report before submitting it.','The first paragraph introduces the research question.','She wrote the word on a paperclip.','这里 paragraph 作动词，表示把报告分段。',2,'usage')]);
P('parallel','Parallel comes from Greek parallēlos, “beside one another”; it means equidistant lines, corresponding events or things, a comparable case, or to resemble.',[C('parallel.s1','平行的；并行的','The two parallel paths crossed the plain without ever meeting.','两条平行的小路穿过平原，始终没有相交。','The two parallel paths / crossed the plain / without ever meeting.','几何义 parallel 描述处于同一平面且永不相交的线或路径。','两条路始终保持间距。'),C('parallel.s2','同时发生的；对应的','A parallel investigation by another team reached the same conclusion in March.','另一支团队同时开展的调查也在三月得出了相同结论。','A parallel investigation by another team / reached the same conclusion / in March.','parallel 可形容同时进行或彼此对应的活动。','两项调查同时进行并得到相同结果。'),C('parallel.s3','相似之处；可相比的事物','Historians found a close parallel between the two reforms, although they occurred a century apart.','历史学家发现这两项改革很相似，尽管它们相隔一个世纪。','Historians found a close parallel / between the two reforms / although they occurred a century apart.','parallel 作名词可指可比较的相似事物或情况。','两次改革在性质上相似。'),C('parallel.s4','与……相似；与……同时发生','The rise in household costs parallels the decline in the value of local wages.','家庭开支上升与当地工资购买力下降同时发生。','The rise in household costs / parallels the decline / in the value of local wages.','parallel 作动词可表示与……相似或同时发生。','成本上升与工资购买力下降相伴。')],M('The two parallel lines were described as never meeting, but the diagram showed them crossing each other twice.','The two parallel lines were described as never meeting, and the diagram showed them keeping the same distance apart.','几何中的平行线保持间距且永不相交；图上相交与此矛盾。','meaning'),[q('How did the two paths relate to each other?','they stayed apart and never met','they crossed at the center of the plain','one path ended at the other’s starting point','平行小路始终保持距离，没有相交。',1,'context'),q('What did the second team’s parallel investigation do?','it proceeded alongside the first and reached the same conclusion','it was completed a century before the first began','it changed the value of local wages','parallel 调查是同时或对应进行的调查。',2,'context'),q('What is a close parallel between reforms?','a comparable similarity between them','a line that crosses both reforms','a list of unrelated dates','parallel 作名词指可比较的相似情况。',3,'meaning'),q('In the final sentence, what does parallels mean?','happens alongside or corresponds to','is physically perpendicular to','has no relation to','成本上升与工资购买力下降同时或对应发生。',4,'meaning')]);
P('parallelism','Parallelism is formed from parallel and the noun-forming suffix -ism; it names a matching arrangement of lines, ideas, clauses, or events.',C('parallelism.s1','平行关系；排比','The editor improved the speech’s parallelism by making each item in the three-part list begin with a verb.','编辑让三项列表都以动词开头，从而改善了演讲中的排比结构。','The editor improved the speech’s parallelism / by making each item / in the three-part list begin with a verb.','parallelism 可指线条的平行，也可指语言结构或事件之间的对应重复。','三个并列项目采用相同语法开头。'),M('The list showed parallelism because its three items used completely unrelated grammatical patterns and no repeated structure.','The list showed parallelism because all three items began with the same grammatical pattern.','平行结构依赖对应形式；完全无关的语法模式不构成此处的排比。','grammar'),[q('How did the editor improve the speech?','each item in the list now begins with a verb','each item now uses a different tense and structure','the list was removed from the speech','三项都以动词开头，形成对应结构。',1,'context'),q('What is rhetorical parallelism?','repetition of a matching grammatical or rhetorical pattern','two geometric lines meeting at a point','a change from one topic to another paragraph','修辞排比采用相似的语法或修辞形式。'),q('Which sentence uses parallelism?','She likes reading, writing, and swimming.','She likes to read, writing, and swims.','She likes books because the weather is cold.','三个动名词并列，形成平行结构。',1,'grammar'),q('What does -ism add to parallelism?','a noun naming a quality, system, or practice','a past-tense verb ending','a plural ending for objects','-ism 构成表示性质或体系的名词。',1,'word-formation')]);
P('parallelogram','Parallelogram comes from Greek parallelogrammon, “bounded by parallel lines”; it is a quadrilateral with both pairs of opposite sides parallel.',C('parallelogram.s1','平行四边形','The student marked both pairs of opposite sides with matching arrows to show that the shape was a parallelogram.','学生在两组对边上标出相同箭头，表示这个图形是平行四边形。','The student marked both pairs of opposite sides / with matching arrows / to show that the shape was a parallelogram.','parallelogram 是两组对边分别平行的四边形。','箭头标记表示每一组对边平行。'),M('The teacher identified the quadrilateral as a parallelogram even though only one pair of opposite sides was parallel.','The teacher identified the quadrilateral as a parallelogram because both pairs of opposite sides were parallel.','平行四边形要求两组对边都平行；只有一组不够。','meaning'),[q('What did the matching arrows show?','both pairs of opposite sides were parallel','all four sides had different lengths','the shape had five corners','箭头标出两组对边平行。',1,'context'),q('How many sides does a parallelogram have?','four','three','six','平行四边形是四边形。',1,'meaning'),q('Which shape is a parallelogram?','a quadrilateral with both pairs of opposite sides parallel','a triangle with one curved side','a circle with a marked center','平行四边形有两组平行对边。',1,'meaning'),q('Which word part points to the parallel sides?','parallelo-','-gram','-ness','parallelo- 对应“平行”，指图形的边关系。',1,'word-formation')]);
P('paralyse','Paralyse is the chiefly British spelling of paralyze, from French paralyser and Latin paralysis; it means to disable movement or stop a system.',C('paralyse.s1','使麻痹；使瘫痪','A spinal injury can paralyse the legs, so the patient began careful rehabilitation with her medical team.','脊髓损伤可能使双腿瘫痪，因此患者在医疗团队帮助下开始谨慎康复。','A spinal injury can paralyse the legs / so the patient began careful rehabilitation / with her medical team.','paralyse 是及物动词，可指使身体失去运动能力，也可比喻使系统无法运作。','损伤导致双腿失去运动能力。'),M('The injury paralysed his legs, but he could immediately walk normally without treatment or support.','The injury paralysed his legs, leaving him unable to move them normally.','paralyse 指使身体部位不能运动；立即正常行走与该结果相反。','meaning'),[q('What could the spinal injury do?','make the patient’s legs unable to move','make the legs stronger instantly','change the patient’s eye color','脊髓损伤可能使双腿瘫痪。'),q('Which spelling is chiefly British?','paralyse','paralize','paralizee','paralyse 是主要用于英式英语的拼写。',1,'spelling'),q('What does paralyse mean figuratively when a strike paralyses a city?','it stops normal activity across the city','it makes every resident physically ill','it improves all transport services','比喻用法表示使城市的正常运转停摆。',1,'meaning'),q('Which sentence uses paralyse correctly?','The sudden outage paralysed the ticket system.','The outage paralysed by the station quickly.','The system paralysed the passengers to arrive early.','停电使售票系统无法运作，符合该动词用法。',1,'usage')]);
P('paralysed','Paralysed is the British -s- spelling of the past participle and adjective from paralyse; it describes loss of movement or inability to act.',C('paralysed.s1','瘫痪的；呆住的','The rescue team found the climber paralysed by fear at the edge of the ledge, unable to take another step.','救援队发现登山者在悬崖边吓得呆住，无法再迈出一步。','The rescue team found the climber paralysed by fear / at the edge of the ledge / unable to take another step.','paralysed 可指身体瘫痪，也可指因恐惧或震惊而无法行动。','fear 造成无法迈步的状态。'),M('She was paralysed by fear, yet she calmly rushed forward and acted without hesitation.','She was paralysed by fear and could not move forward or make a decision.','被恐惧吓得呆住意味着难以行动，不是镇定而毫不迟疑地行动。','meaning'),[q('Why could the climber not take another step?','fear had left him unable to act','his boots were made of paper','he had already reached a safe bus station','恐惧让登山者呆住，无法继续前进。'),q('Which spelling is used in British English?','paralysed','paralyzed','paralysize','英式拼写通常用 s：paralysed。',1,'spelling'),q('What does “paralysed by fear” mean?','so frightened that one cannot act','physically injured in both legs only','calm enough to make a quick plan','这个短语指因害怕而无法行动。',1,'meaning'),q('Which situation fits paralysed in a figurative sense?','an organization unable to decide after a scandal','a team quickly agreeing on a plan','a runner finishing a race on schedule','组织因丑闻无法决策，属于比喻义。',1,'context')]);
P('paralysis','Paralysis came through Latin from Greek paralysis, literally “a loosening,” from para- and lyein, “to loosen”; it means loss of movement or function.',[C('paralysis.s1','麻痹；瘫痪','The fall caused temporary paralysis in his left hand, and doctors monitored his recovery closely.','摔倒导致他的左手暂时麻痹，医生密切观察康复情况。','The fall caused temporary paralysis / in his left hand / and doctors monitored his recovery closely.','paralysis 指身体部分或全部失去运动能力。','左手暂时失去正常运动能力。'),C('paralysis.s2','停顿；瘫痪状态','A paralysis of decision-making delayed the flood response while officials argued over responsibility.','官员们争论责任归属，决策瘫痪延误了洪灾应对。','A paralysis of decision-making delayed the flood response / while officials argued / over responsibility.','paralysis 也可比喻机构或活动无法正常运作。','争论使救灾决策停摆。')],M('The flood response suffered paralysis, so officials made swift decisions and deployed every team immediately.','The flood response suffered paralysis, so officials could not make decisions or deploy teams promptly.','paralysis 比喻决策停顿；迅速决策和部署与停摆相反。','meaning'),[q('What happened to the climber’s hand?','it temporarily lost normal movement','it became stronger after the fall','it was used to check a golf score','左手暂时麻痹。',1,'context'),q('Why was the flood response delayed?','officials argued over responsibility and could not decide','all teams had already completed the rescue','the river stopped flowing before the storm','官员争论导致决策瘫痪。',2,'context'),q('Which is figurative paralysis?','a committee unable to act because members cannot agree','a person moving a healthy arm','a runner breathing quickly after a sprint','委员会无法采取行动是比喻性瘫痪。',2,'meaning'),q('What image lies behind the Greek source of paralysis?','loosening or disabling','a perfect garden','a list of sentence parts','希腊词源字面与“松开”有关，后来指失去运动能力。',1,'word-formation')]);
P('paralyze','Paralyze came through French from Latin paralysis and Greek paralyein; it means to disable movement, thought, or a system.',[C('paralyze.s1','使瘫痪；使丧失活动能力','The nerve disorder can paralyze the muscles that control a person’s hands.','这种神经紊乱可能使控制手部的肌肉瘫痪。','The nerve disorder can paralyze the muscles / that control / a person’s hands.','paralyze 可指使身体部位失去运动能力。','肌肉失去正常运动功能。'),C('paralyze.s2','使呆住；使无法正常思考','The unexpected accusation seemed to paralyze Imani, and she could not answer the reporter for several seconds.','突如其来的指控似乎让伊玛妮呆住了，她好几秒都无法回答记者。','The unexpected accusation seemed to paralyze Imani / and she could not answer the reporter / for several seconds.','paralyze 可比喻因恐惧或震惊而使人暂时无法行动或思考。','指控让她短时间无法作答。'),C('paralyze.s3','使陷于瘫痪；使停止运转','A software failure paralyzed the airport check-in system for nearly an hour.','软件故障使机场值机系统瘫痪了近一个小时。','A software failure paralyzed the airport check-in system / for nearly an hour.','paralyze 也可指使组织、城市或机器系统停止运转。','值机系统近一小时无法工作。')],M('The software failure paralyzed the check-in system, but passengers continued checking in normally at every terminal.','The software failure paralyzed the check-in system, so passengers could not check in until service returned.','系统瘫痪意味着不能正常办理值机；所有人照常办理与故障影响矛盾。','meaning'),[q('Which muscles could the nerve disorder affect?','the muscles controlling the hands','the muscles of a paperclip','the muscles that move a river','神经紊乱可能使手部肌肉瘫痪。',1,'context'),q('How did Imani react to the accusation?','she was briefly unable to answer','she immediately wrote a long essay','she confidently completed the interview','指控让她短暂呆住，无法回答。',2,'context'),q('What did the software failure do?','stopped the check-in system from working','opened every gate automatically','made the airport’s runways longer','故障使值机系统瘫痪。',3,'context'),q('Which spelling is standard in American English?','paralyze','paralyse','paralysee','美式通常采用 z 拼写 paralyze。',1,'spelling')]);
P('parameter','Parameter is a modern formation from Greek para-, “beside,” and metron, “measure”; it is a measurable factor or a boundary condition.',[C('parameter.s1','参数；参量','The model predicts crop yield using rainfall as one parameter alongside soil quality and temperature.','模型把降雨量与土壤质量、温度一起作为预测作物产量的参数。','The model predicts crop yield / using rainfall as one parameter / alongside soil quality and temperature.','parameter 可指用于定义或计算系统结果的可测因素。','降雨量参与产量模型计算。'),C('parameter.s2','界限；范围；规范','The contractor must finish the repair within the agreed budget and time parameters.','承包商必须在约定的预算和工期范围内完成维修。','The contractor must finish the repair / within the agreed budget and time parameters.','parameter 的复数也可指必须遵守的界限或条件。','预算和工期规定了工作的边界。')],M('Rainfall was an important parameter in the model, but the analyst excluded it from every calculation.','Rainfall was an important parameter in the model, so the analyst included it in the crop-yield calculations.','若它是模型参数，就应纳入计算，而不是完全排除。','meaning'),[q('What role did rainfall play in the crop model?','it was a measurable input parameter','it was the final crop itself','it replaced all soil measurements','降雨量是用于预测产量的可测参数。',1,'context'),q('What are the contractor’s time parameters?','the agreed limits on how long the repair may take','the names of the repair crew','the temperature of the paint','工期参数指完成工作的时间界限。',2,'meaning'),q('Which item is a parameter in a weather model?','humidity used to calculate storm risk','a poster displayed in the office','a tool kept in an unrelated drawer','湿度作为可测因素参与风险计算。',1,'context'),q('What does metron mean in the source of parameter?','measure','garden','fear','希腊语 metron 表示“测量”。',1,'word-formation')]);
P('paramilitary','Paramilitary combines para-, here “alongside or resembling,” with military; it describes an organized force operating like an army but outside the official armed forces.',C('paramilitary.s1','准军事的','The report described the paramilitary group as armed and organized like a military unit but not part of the national army.','报告称该准军事组织有武装、组织方式类似军队，但不属于国家正规军。','The report described the paramilitary group / as armed and organized like a military unit / but not part of the national army.','paramilitary 形容组织或力量具有类似军队的结构或训练，却不属于正规军。','报告明确对比其军队式组织与非正规军身份。'),M('The report called the force paramilitary because it was the country’s official army under direct military command.','The report called the force paramilitary because it operated like an army but remained outside the official armed forces.','paramilitary 表示类似军队但非正规军；官方军队身份不符合该定义。','meaning'),[q('What made the group paramilitary?','it was organized like a military unit but outside the national army','it was the country’s regular army','it had no weapons or organized structure','该组织具备军队式组织但不属正规军。',1,'context'),q('Which force is most likely paramilitary?','an armed volunteer group trained and organized like soldiers','a national army unit under official command','a neighborhood book club','准军事力量类似军队但不属于正规军。',1,'meaning'),q('What does para- contribute here?','alongside or resembling','a method of measuring','a state-shaped strip of land','此处 para- 表示“类似”或“在旁”。',1,'word-formation'),q('Which distinction matters in the report?','the group is army-like but not the official army','the group is unarmed and has no structure','the group consists only of elected lawmakers','该词的关键是军队式特征与非正规军身份并存。',1,'context')]);
P('paramount','Paramount came from Anglo-French and Old French paramont, “above”; it means supreme or more important than all competing considerations.',C('paramount.s1','首要的；至高的','During the evacuation, keeping every resident safe was paramount, even if some belongings had to be left behind.','撤离期间，保障每位居民安全是首要任务，即使必须留下部分物品。','During the evacuation / keeping every resident safe was paramount / even if some belongings had to be left behind.','paramount 形容重要性高于其他考虑的事项。','人员安全优先于财物。'),M('The rescue chief said speed was paramount, but ordered the team to place minor paperwork ahead of everyone’s safety.','The rescue chief said safety was paramount and ordered the team to protect people before collecting paperwork.','paramount 表示首要优先；把琐碎文件排在人员安全之前不符合该优先级。','meaning'),[q('What was paramount during the evacuation?','keeping residents safe','collecting every household object','finishing paperwork before moving anyone','撤离时居民安全最重要。'),q('Which concern is paramount in an emergency rescue?','preventing serious harm to people','choosing the color of a sign','preserving an unused pamphlet','紧急救援中，避免人员受伤是首要事项。',1,'meaning'),q('What is the relation between paramount and other priorities?','it outranks them in importance','it is always less important','it describes a place above a mountain only','paramount 表示重要性高于其他事项。',1,'meaning'),q('What older French idea underlies paramount?','being above in place or degree','being beside each other in parallel lines','being completely silent on stage','旧法语来源意为位置或程度上“在上面”。',1,'word-formation')]);
P('paranoia','Paranoia comes from Greek paranoia, “derangement,” formed from para-, “beside,” and noos, “mind”; today it often means unjustified suspicion.',C('paranoia.s1','偏执多疑','After a series of harmless delays, his paranoia made him suspect that every colleague was secretly plotting against him.','几次无关紧要的延误后，他的多疑让他怀疑每位同事都在暗中算计他。','After a series of harmless delays / his paranoia made him suspect / that every colleague was secretly plotting against him.','paranoia 指缺乏充分依据的强烈猜疑；日常表达中也可泛指过度多疑。','普通延误被解释成所有同事的阴谋。'),M('Her paranoia was justified by clear evidence of a real threat, so she had no suspicious thoughts without evidence.','Her paranoia led her to suspect a plot even though the delays were harmless and offered no evidence.','paranoia 在此指缺乏依据的猜疑；明确证据支持的合理警惕并非这一义项。','meaning'),[q('What made him suspect his colleagues?','harmless delays were interpreted as a secret plot','he found a signed confession from each colleague','the team openly announced a plan to help him','无害延误让他无依据地怀疑同事。',1,'context'),q('What does paranoia usually involve?','unjustified suspicion','a measured boundary in a model','a short story teaching a lesson','paranoia 通常指缺少依据的猜疑。',1,'meaning'),q('Which reaction most clearly suggests paranoia?','assuming neighbors are spying despite no supporting evidence','checking a locked door once before bed','reporting a documented theft to the police','没有依据却认为邻居在监视自己，表现出多疑。',1,'context'),q('What does the Greek element noos refer to?','mind','gold','a garden enclosure','noos 表示“心智”。',1,'word-formation')]);
P('paraphasia','Paraphasia is a clinical term formed from para- and Greek phasis, “speech”; it describes substituting incorrect words or speech sounds.',C('paraphasia.s1','语言错乱；错语','After the stroke, the patient sometimes said “chair” when she meant “table,” a symptom the clinician recorded as paraphasia.','中风后，患者有时想说“桌子”却说成“椅子”，临床医生将这种症状记录为错语。','After the stroke / the patient sometimes said “chair” when she meant “table” / a symptom the clinician recorded as paraphasia.','paraphasia 是说话时无意替换成错误词语或音节的语言症状。','患者实际说出的词和想表达的词不一致。'),M('The clinician recorded paraphasia when the patient consistently chose the exact word she intended to say.','The clinician recorded paraphasia when the patient unintentionally substituted the wrong word for the one she meant.','paraphasia 指无意错换词语；准确说出想表达的词不是该症状。','meaning'),[q('What substitution did the clinician observe?','“chair” was said when the patient meant “table”','“table” was said correctly when she meant “table”','a whole paragraph was omitted from a report','她想说“桌子”却说成“椅子”。',1,'context'),q('What is paraphasia?','unintended substitution of an incorrect word or sound','a deliberate paraphrase of a sentence','a loss of movement in the legs','paraphasia 是说话中的无意错语或音节替换。',1,'meaning'),q('Which event is an example of paraphasia?','a speaker says “fork” while intending to say “spoon”','a speaker repeats a sentence to make it clearer','a speaker forgets where a paperclip is stored','说错词替代本想说的词，符合错语。',1,'context'),q('Which part of the term points to speech?','phasis','para-','-phobia','希腊语 phasis 与说话、表达有关。',1,'word-formation')]);
P('paraphernalia','Paraphernalia originally meant a woman’s property apart from her dowry, from Greek para-, “beside,” and pherne, “dowry”; it now means equipment and miscellaneous items.',C('paraphernalia.s1','随身器具；一堆装备','The photographer packed her lighting paraphernalia, including stands, cables, clamps, and spare bulbs.','摄影师收拾了灯光设备，包括支架、电缆、夹具和备用灯泡。','The photographer packed her lighting paraphernalia / including stands, cables / clamps and spare bulbs.','paraphernalia 通常指与某项活动相关的一批器具、装备或零碎物品。','列举的都是摄影灯光设备。'),M('The photographer packed her lighting paraphernalia, but the case contained no tools, equipment, or related items.','The photographer packed her lighting paraphernalia, including the stands, cables, clamps, and bulbs she needed.','paraphernalia 指一批相关器具；说箱中没有任何装备与随后列举冲突。','meaning'),[q('What did the photographer pack?','stands, cables, clamps, and spare bulbs','a single unrelated paperback','a list of golf scores','她装的是摄影灯光设备。',1,'context'),q('What does paraphernalia usually refer to today?','equipment and associated odds and ends','a formal speech divided into paragraphs','a state’s narrow geographic extension','该词现常指某活动的器具和零碎装备。',1,'meaning'),q('Which collection is paraphernalia?','the brushes, paints, cloths, and tools used by a muralist','one sealed envelope unrelated to painting','a single line on a graph','壁画师使用的一批绘画器具属于 paraphernalia。',1,'context'),q('What did para- mean in the term’s original legal history?','beside or apart from','above a mountain','at the same distance','原词义涉及嫁妆以外、附加的财产。',1,'word-formation')]);
P('paraphrase','Paraphrase comes from Greek paraphrasis, “a way of expressing,” from para-, “beside,” and phrasis, “speech”; it is a restatement in different words.',[C('paraphrase.s1','释义；改述','Her paraphrase kept the scientist’s conclusion but replaced the technical wording with language the public could understand.','她的改述保留了科学家的结论，却把专业措辞换成公众能理解的语言。','Her paraphrase kept the scientist’s conclusion / but replaced the technical wording / with language the public could understand.','paraphrase 作名词指用不同措辞重述原文，同时保留原意。','结论不变，措辞变得更易懂。'),C('paraphrase.s2','意译；改述','Please paraphrase the final paragraph in your own words rather than copying the author’s sentences.','请用自己的话改述最后一段，不要照抄作者的句子。','Please paraphrase the final paragraph / in your own words / rather than copying the author’s sentences.','paraphrase 作动词表示用自己的话改述他人的表达。','明确要求换成自己的措辞。')],M('The student paraphrased the source by copying every sentence word for word and keeping the original wording unchanged.','The student paraphrased the source by restating its ideas in different words while keeping the meaning.','paraphrase 要换用措辞表达原意；逐字照抄不是改述。','usage'),[q('What did the scientist’s paraphrase preserve?','the conclusion while changing technical wording','the exact wording and every sentence','a different conclusion unrelated to the study','改述保留结论，同时把术语换成易懂表达。',1,'context'),q('What does the teacher ask students to do?','restate the paragraph in their own words','copy every sentence exactly','remove the paragraph from the essay','教师要求用自己的话改述。',2,'context'),q('Which action is paraphrasing?','explaining a source idea with new wording and the same meaning','quoting the source word for word without attribution','changing the source’s conclusion to its opposite','改述用新措辞表达相同意思。',2,'meaning'),q('What is the relation between paraphrase as a noun and verb?','the noun is a restatement; the verb is to make one','the noun is a geometric curve; the verb is to draw it','the noun is equipment; the verb is to pack it','paraphrase 名词指改述内容，动词指进行改述。',1,'usage')]);
P('parapsychology','Parapsychology is from German para-psychologie, combining para-, “beside or beyond,” with psychology; it studies claimed extrasensory phenomena.',C('parapsychology.s1','心灵学','The article reviewed parapsychology experiments on telepathy and clairvoyance, while noting that the claims remain disputed.','文章评述了有关心灵感应和千里眼的心灵学实验，同时指出这些主张仍有争议。','The article reviewed parapsychology experiments / on telepathy and clairvoyance / while noting that the claims remain disputed.','parapsychology 指研究心灵感应、超感知等超出常规心理学范畴现象的领域。','文章列举了该领域常研究的现象，并说明其争议性。'),M('The article called parapsychology the study of ordinary memory tests and excluded all claims about telepathy or clairvoyance.','The article called parapsychology the study of claimed phenomena such as telepathy and clairvoyance.','parapsychology 聚焦超常心理现象；普通记忆测验不能体现该领域的典型研究对象。','meaning'),[q('Which phenomena did the article review?','telepathy and clairvoyance','the movement of parallel lines','the growth of marsh plants','文章评述了心灵感应和千里眼实验。'),q('What does parapsychology investigate?','claims about extrasensory or unusual mental phenomena','only ordinary vocabulary learning','the mathematical properties of curves','该领域研究超出常规心理学范畴的现象主张。',1,'meaning'),q('How did the article describe the evidence?','the claims remain disputed','every claim was proven beyond doubt','the experiments studied no mental phenomena','文章指出这些主张仍有争议。',1,'context'),q('What does para- suggest in parapsychology?','beside or beyond ordinary psychology','a shield against the sun','a measure of rainfall','para- 表示“旁边”或“超出”。',1,'word-formation')]);
P('parasite','Parasite comes from Greek parasitos, “one who eats at another’s table,” from para-, “beside,” and sitos, “food”; it can be an organism or an exploitative person.',[C('parasite.s1','寄生生物；寄生虫','The tick is a parasite that feeds on its host and can transmit disease.','蜱虫是一种寄生虫，它靠宿主为生，还可能传播疾病。','The tick is a parasite / that feeds on its host / and can transmit disease.','parasite 作生物学名词指生活在宿主体内或体表并从中获取养分的生物。','蜱虫从宿主获取食物。'),C('parasite.s2','靠他人为生的人；食客','The landlord called the fraudster a parasite because he took rent money from tenants but never repaired the building.','房东称那个骗子是寄生虫，因为他收取租客房租却从不维修大楼。','The landlord called the fraudster a parasite / because he took rent money / but never repaired the building.','parasite 也可贬义地指依靠他人却不给予回报的人。','人物获取他人钱财而不承担责任。')],M('The tick was a parasite, but it provided food and protection to the host without taking anything from it.','The tick was a parasite because it took nourishment from the host and could harm it.','寄生生物从宿主获取食物或资源；题干却说它只提供帮助。','meaning'),[q('How does the tick get food?','it feeds on its host','it produces its own food from rent money','it eats only fallen paper','蜱虫依靠宿主获取养分。',1,'context'),q('Why was the fraudster called a parasite?','he took money from tenants without maintaining the building','he repaired every apartment at no charge','he paid rent to every tenant','他靠租客的钱获利，却不维修房屋。',2,'context'),q('What is a biological parasite?','an organism that lives on or in a host and takes resources from it','an organism that always improves its host’s health','a creature that cannot interact with another organism','生物学 parasite 依靠宿主获取资源。',1,'meaning'),q('What did Greek sitos mean in the source word?','food','wall','speak','sitos 表示“谷物、食物”。',1,'word-formation')]);
P('parasitic','Parasitic comes from Greek parasitikos, “of a parasite”; it describes an organism feeding on a host or a relationship that takes without giving back.',C('parasitic.s1','寄生的','The parasitic vine wrapped around the tree and drew water and nutrients from its living host.','这株寄生藤缠绕着树，从活的宿主身上吸取水分和养分。','The parasitic vine wrapped around the tree / and drew water and nutrients / from its living host.','parasitic 形容依靠宿主获取养分的生物，也可形容类似的依赖关系。','藤从宿主吸取资源。'),M('The parasitic vine was described as parasitic even though it made its own food and took nothing from the tree.','The parasitic vine was described as parasitic because it drew water and nutrients from the tree.','parasitic 的生物义强调依靠宿主；不取用宿主资源与该义不符。','meaning'),[q('What did the vine take from the tree?','water and nutrients','gold and paper','sunlight from an indoor lamp only','藤从宿主树获取水分和养分。'),q('Which relationship is parasitic?','one organism feeds on a host while harming or burdening it','two species exchange benefits equally','a gardener waters an independent plant','寄生关系中一方从宿主获取资源。',1,'meaning'),q('How is parasitic related to parasite?','it is the adjective describing a parasite or its behavior','it is the past tense of parasite','it means a tool used to remove parasites','parasitic 是形容 parasite 的形容词。',1,'word-formation'),q('Which phrase uses parasitic figuratively?','a parasitic business that survives by exploiting unpaid workers','a mutual partnership where both groups contribute','a neutral schedule for shared meetings','剥削他人而单方面获益的关系可比喻为寄生。',1,'usage')]);
P('parasitism','Parasitism is formed from parasite and -ism; it names a way of life in which one organism depends on a host for resources.',C('parasitism.s1','寄生状态','The ecologist studied parasitism by measuring how the insect’s larvae affected the fish host.','生态学家通过测量昆虫幼虫对鱼类宿主的影响来研究寄生状态。','The ecologist studied parasitism / by measuring how the insect’s larvae affected / the fish host.','parasitism 指寄生者依靠宿主获取资源的生存关系。','研究者测量寄生者对宿主的影响。'),M('The study called parasitism a relationship in which neither organism depends on or affects the other.','The study called parasitism a relationship in which a parasite depends on a host and affects it.','寄生关系包含寄生者对宿主的依赖；完全互不影响不是该关系。','meaning'),[q('What did the ecologist measure?','how insect larvae affected their fish host','how a paperclip held survey sheets','how a parkway crossed a town','生态学家测量幼虫对鱼类宿主的影响。'),q('What defines parasitism?','one organism depends on a host and takes resources','two organisms never interact','both organisms always receive exactly equal benefits','寄生状态是一方依赖宿主获取资源。',1,'meaning'),q('Which example illustrates parasitism?','a tapeworm living in an animal and taking nutrients','two plants sharing sunlight without affecting each other','bees pollinating flowers while collecting nectar','绦虫从动物体内获取养分，是寄生关系。',1,'context'),q('What does the suffix -ism help form in parasitism?','a noun for a condition or kind of relationship','a comparative adjective','a past-tense verb','-ism 构成表示状态或关系类型的名词。',1,'word-formation')]);
P('parasol','Parasol came from French via Italian parasole, literally “protection from the sun,” from para-, “defense against,” and sole, “sun.”',C('parasol.s1','阳伞','She opened a lace parasol to shade her face while she waited beside the sunny garden path.','她在阳光明媚的花园小径旁等候时撑开蕾丝阳伞遮脸。','She opened a lace parasol / to shade her face / beside the sunny garden path.','parasol 指用来遮挡阳光的轻便伞具。','她撑伞是为了遮阳而非避雨。'),M('She opened her parasol to keep the rain off during the storm, although the account said it was designed only for sun protection.','She opened her parasol to shade herself from the strong sunlight.','parasol 的词源和常见用途都指向遮阳，题干把用途改成防雨。','meaning'),[q('Why did she open the parasol?','to shade her face from the sun','to catch leaves in the garden','to measure the garden path','她撑开阳伞是为了遮阳。'),q('Which object is a parasol?','a light umbrella carried to block sunlight','a heavy tent fixed over a campsite','a wire clip fastening papers','parasol 是用于遮挡阳光的轻便伞。',1,'meaning'),q('What does Italian sole mean in parasole?','sun','paper','wall','sole 在该词中表示“太阳”。',1,'word-formation'),q('Which situation calls for a parasol?','walking on a sunny path and wanting shade','crossing a flooded river by boat','storing a book on a shelf','阳伞适用于晴天遮阳。',1,'context')]);
P('parcel','Parcel came through Old French and Medieval Latin from Latin particella, “small part”; it means a package or plot of land and can mean divide or wrap into parts.',[C('parcel.s1','包裹；小包','The courier left a parcel containing the repaired camera at the apartment’s front desk.','快递员把装有修好相机的包裹留在公寓前台。','The courier left a parcel / containing the repaired camera / at the apartment’s front desk.','parcel 作名词可指包好后邮寄或携带的一件物品。','包裹里装有待领取的相机。'),C('parcel.s2','一块（土地）','The family bought a small parcel of land beside the river to build a greenhouse.','这家人在河边买下一小块土地，准备建温室。','The family bought a small parcel of land / beside the river / to build a greenhouse.','parcel of land 指经划定的一块土地。','房产交易对象是一块具体土地。'),C('parcel.s3','分配；把……分成小包','The relief coordinator parceled the food into equal boxes for delivery to each shelter.','救援协调员把食物分装成等量的箱子，送往各个避难所。','The relief coordinator parceled the food / into equal boxes / for delivery to each shelter.','parcel 作动词可把物品分成若干部分或包裹后分发。','食物被分成等量箱子并分送。')],M('The courier marked the box as a parcel, but left every item loose and unpacked on the sidewalk.','The courier marked the wrapped box containing the camera as a parcel.','parcel 作邮寄义是包裹；散落未包装的物品不是一个包裹。','meaning'),[q('What was inside the courier’s parcel?','the repaired camera','a plot of land','a bowl of river water','包裹中装着修好的相机。',1,'context'),q('What did the family purchase beside the river?','a small plot of land','a package from the courier','a greenhouse already built','parcel of land 指一块土地。',2,'context'),q('What did the coordinator do when she parceled the food?','divided it into boxes for separate delivery','threw it away without sorting','planted it beside the river','她把食物分成箱子并分发。',3,'context'),q('What does the Latin source particella suggest?','a small part or piece','a sunshade','a way of speaking','parcel 的词源与“部分、小片”有关。',1,'word-formation')]);
P('parch','Parch has an uncertain history; it means to dry or scorch with strong heat, and Etymonline cautions that proposed origins are disputed.',C('parch.s1','烤干；使焦干','The desert wind began to parch the exposed soil, leaving cracks across the field by noon.','沙漠的风开始把裸露的土壤烤干，中午时田地上已布满裂缝。','The desert wind began to parch the exposed soil / leaving cracks across the field / by noon.','parch 指强热使土地、植物或喉咙变得干燥。','强风和高温使土壤失水开裂。'),M('The dry heat parched the field, leaving the soil soaked and muddy for days.','The dry heat parched the field, leaving the soil hard and cracked.','parch 表示烤干；湿透泥泞与缺水干裂相反。','meaning'),[q('What did the desert wind do to the soil?','dried it until cracks appeared','soaked it until it became muddy','covered it with a layer of ice','风和高温把土壤烤干并使其开裂。'),q('Which condition can parch a person’s throat?','hot dry air','a cool drink of water','a shaded room with a humidifier','干热空气可能使喉咙干燥。',1,'context'),q('What does parch mean?','dry out or scorch with strong heat','cover with a soft blanket','divide into equal parcels','parch 表示受强热而干燥或焦干。',1,'meaning'),q('What is known about the word’s origin?','its history is uncertain and proposed origins are disputed','it certainly comes from the Latin word for paper','it was coined as a name for a desert wind','该词源存在争议，不能武断地指定来源。',1,'word-formation')]);
P('parched','Parched is the past participle and adjective from parch; it describes something dried out by heat or lack of water.',C('parched.s1','干透的','After the long hike, the parched hikers searched for a stream and drank slowly.','长途徒步后，干渴的徒步者四处寻找溪流，并慢慢喝水。','After the long hike / the parched hikers searched for a stream / and drank slowly.','parched 可形容因缺水或炎热而干透的土地、植物，也可形容口渴的人。','徒步后寻找水源表明他们口渴。'),M('The parched field was so dry that water pooled across its flooded surface.','The parched field was so dry that its cracked surface absorbed the first drops of rain.','parched 表示干透，水在表面大量积聚与干燥状态不符。','meaning'),[q('What did the parched hikers look for?','a stream for water','a shaded theater','a package at the station','他们徒步后口渴，寻找溪流。'),q('Which soil is parched?','dry, cracked soil after weeks without rain','waterlogged soil beneath a flooded river','freshly watered soil in a greenhouse','缺雨而干裂的土壤是 parched。',1,'meaning'),q('What does parched mean in “a parched throat”?','very dry and thirsty','cold and numb','unable to speak because of fear only','parched throat 指非常干渴的喉咙。',1,'meaning'),q('How is parched formed?','it is the past participle and adjective from parch','it is the plural of parchment','it is the present tense of parcel','parched 是 parch 的过去分词，也作形容词。',1,'word-formation')]);
P('parchment','Parchment comes through Old French and Medieval Latin from Late Greek pergamenon, “of Pergamon,” where the material was reportedly used.',C('parchment.s1','羊皮纸','The conservator placed the medieval charter on a support because the parchment had become brittle with age.','羊皮纸因年代久远变得脆弱，修复师便把中世纪特许状放在托板上。','The conservator placed the medieval charter on a support / because the parchment / had become brittle with age.','parchment 指经处理的羊皮或山羊皮书写材料，也可指仿羊皮纸的纸。','古老特许状使用的材料需要特殊保护。'),M('The conservator called the charter parchment, although it was made from a thin sheet of modern plastic.','The conservator called the charter parchment because it was written on prepared animal skin.','parchment 的传统义是处理后的动物皮书写材料，不是塑料。','meaning'),[q('Why did the conservator use a support?','the old parchment had become brittle','the paperclip was too small','the charter was printed on a flexible paperback cover','羊皮纸年代久远，变得脆弱。'),q('What is traditional parchment made from?','prepared sheep or goat skin','pressed reeds from a modern newspaper','bent wires from a paperclip','羊皮纸传统上由处理过的羊皮或山羊皮制成。',1,'meaning'),q('Which document would most likely be written on parchment?','a medieval charter preserved in an archive','a text message on a phone screen','a grocery receipt printed this morning','古代档案可能使用羊皮纸。',1,'context'),q('What place is named in the Greek source pergamenon?','Pergamon','Paris','Pangaea','pergamenon 意为“来自 Pergamon 的”。',1,'word-formation')]);
P('pardon','Pardon came from Old French and Latin perdonare, “to give wholeheartedly or remit”; it can mean forgiveness, official release, forgive, or “please repeat.”',[C('pardon.s1','原谅；宽恕','Maya asked her friend’s pardon for arriving late and immediately explained what had happened.','玛雅为迟到向朋友道歉，请求原谅，并立即说明了情况。','Maya asked her friend’s pardon / for arriving late / and immediately explained what had happened.','pardon 作名词可指因过错而得到的宽恕。','她为迟到请求朋友宽恕。'),C('pardon.s2','赦免；特赦','The governor issued a pardon that canceled the prisoner’s remaining sentence.','州长签发了特赦令，免除了囚犯剩余刑期。','The governor issued a pardon / that canceled the prisoner’s remaining sentence.','pardon 也可指官方免除刑罚的决定。','州长的决定正式取消剩余刑期。'),C('pardon.s3','原谅；赦免','The judge pardoned the first-time offender after she completed the required community service.','初犯完成规定的社区服务后，法官赦免了她。','The judge pardoned the first-time offender / after she completed / the required community service.','pardon 作动词可指宽恕过错或正式免除刑罚。','法官采取正式赦免行动。'),C('pardon.s4','对不起，请再说一遍','“Pardon?” asked Luis when the announcement was muffled by the station noise.','车站噪声盖住了广播时，路易斯问：“对不起，请再说一遍？”','“Pardon?” asked Luis / when the announcement was muffled / by the station noise.','单独说 Pardon? 可礼貌地表示没听清、请求对方重复。','广播被噪声盖住，因此他没听清。')],M('The governor granted a pardon that added five years to the prisoner’s sentence and refused to remit any penalty.','The governor granted a pardon that canceled the prisoner’s remaining sentence.','官方 pardon 是免除刑罚，不是增加刑期。','meaning'),[q('Why did Maya ask her friend’s pardon?','she arrived late','she lost the governor’s document','she could not hear the station announcement','玛雅因迟到向朋友请求原谅。',1,'context'),q('What did the governor’s pardon do?','canceled the remaining sentence','added five years to the sentence','required the prisoner to move to another town','特赦免除了囚犯剩余刑期。',2,'context'),q('What did the judge do when she pardoned the offender?','forgave or officially released her from punishment','asked her to repeat a muffled announcement','divided her sentence into parcels','pardon 作动词表示宽恕或赦免。',3,'meaning'),q('Why did Luis say “Pardon?”','he wanted the announcement repeated','he was granting an official release','he was apologizing for arriving late','这里 Pardon? 表示没听清，请对方重复。',4,'usage')]);
P('pare','Pare comes through Old French parer from Latin parare, “prepare or make ready”; it means peel or trim an outer layer and, figuratively, reduce.',[C('pare.s1','削皮','She used a small knife to pare the pear before slicing it for the tart.','她用小刀给梨削皮，然后把它切片做馅饼。','She used a small knife to pare the pear / before slicing it / for the tart.','pare 指削去水果或蔬菜的外皮、外层。','她先去掉梨皮，再切片。'),C('pare.s2','削减；减少','The committee pared the proposal down to three practical steps after the budget was cut.','预算削减后，委员会把提案精简为三个可行步骤。','The committee pared the proposal down / to three practical steps / after the budget was cut.','pare down 可比喻逐步删减、削减数量或规模。','提案内容被逐步缩减。')],M('She pared the pear by leaving all of its skin on and adding a second layer of peel.','She pared the pear by cutting away its outer skin before slicing it.','pare 表示削去外皮，不是保留或增加果皮。','meaning'),[q('What did she remove from the pear?','its outer skin','its seeds and stem only','the tart’s crust','她先给梨削皮。',1,'context'),q('What happened to the proposal after the budget cut?','it was reduced to three steps','it expanded to include every possible project','it was turned into a pear tart','委员会把提案精简为三个步骤。',2,'context'),q('Which sentence uses pare figuratively?','The editor pared the report to its essential points.','The chef pared a pear before lunch.','The runner panted on the hill.','删减报告内容是 pare 的比喻用法。',2,'meaning'),q('Which older Latin verb is linked to pare?','parare, “prepare or make ready”','paraly̆ein, “disable”','paradeigma, “example”','pare 经由法语关联拉丁语 parare。',1,'word-formation')]);
P('parent','Parent came through Old French from Latin parentem, “father or mother,” from parire, “bring forth”; it can name a caregiver, source organism, or the act of raising a child.',[C('parent.s1','父；母；双亲之一','Each parent signed the school form so the child could join the overnight field trip.','每位家长都在学校表格上签了字，孩子才能参加过夜实地考察。','Each parent signed the school form / so the child could join / the overnight field trip.','parent 作名词指父亲或母亲。','签署孩子活动许可的是家长。'),C('parent.s2','亲本；母体；起源物','The researchers compared the hybrid plant with each parent species to identify inherited traits.','研究人员把杂交植物与两个亲本物种进行比较，以识别遗传特征。','The researchers compared the hybrid plant / with each parent species / to identify inherited traits.','parent 也可指产生后代、子代或衍生物的生物或来源。','亲本物种提供遗传特征。'),C('parent.s3','养育；做……的父母','They parented three foster children together and kept in touch with each child’s caseworker.','他们共同养育了三名寄养儿童，并与每个孩子的个案社工保持联系。','They parented three foster children together / and kept in touch / with each child’s caseworker.','parent 作动词可表示承担父母职责、养育孩子。','动词后接需要照料的儿童。')],M('The plant was the parent of the hybrid, but it had no genetic relationship to the offspring and supplied no inherited traits.','The plant was a parent of the hybrid because it supplied inherited traits to the offspring.','生物学 parent 是产生后代的亲本；完全没有遗传关系与此不符。','meaning'),[q('Who signed the school form?','each parent','the bus driver and guide','the plant researcher','家长签署了孩子的活动许可。',1,'context'),q('Why did researchers compare each parent species with the hybrid?','to identify inherited traits','to locate a school form','to measure the plant’s parking space','亲本物种有助于识别遗传特征。',2,'context'),q('What does parent mean as a verb in the foster-care example?','raise and care for children','produce a scientific report','sign a letter on behalf of a plant','parent 作动词表示承担养育职责。',3,'meaning'),q('Which source verb is connected with Latin parentem?','parire, “bring forth or give birth”','parare, “make ready”','parabole, “comparison”','parent 与拉丁语 parire“生育、产生”有关。',1,'word-formation')]);
P('parental','Parental comes from Latin parentalis, “of parents,” built on parens; it means relating to a mother or father.',C('parental.s1','父母的','The school requested parental consent before allowing students to join the overnight science trip.','学校要求取得父母同意后，才允许学生参加过夜科学考察。','The school requested parental consent / before allowing students to join / the overnight science trip.','parental 是形容词，表示与父母或家长有关。','同意由学生家长提供。'),M('The school required parental consent, but it specifically rejected permission from every student’s mother or father.','The school required permission from a student’s parent or guardian before the trip.','parental consent 就是父母或监护人同意，拒绝家长许可与要求矛盾。','meaning'),[q('What did the school need before the trip?','permission from a parent or guardian','a parcel of land','a scientific model of a curve','学校要求家长许可。'),q('What does parental mean?','relating to a parent or parents','relating to a child’s school bus','relating to a plant’s leaves only','parental 表示“父母的、与家长有关的”。',1,'meaning'),q('Which phrase uses parental correctly?','parental responsibilities','parential responsibilities','parentalize responsibility','parental responsibilities 是“父母职责”的正确搭配。',1,'usage'),q('From which noun is parental formed?','parent','parade','parasol','parental 由 parent 加形容词后缀构成。',1,'word-formation')]);
P('parenting','Parenting is the verbal noun from parent; it means the work of caring for and raising children as their parent.',C('parenting.s1','父母的养育；育儿','The workshop discussed parenting strategies for helping toddlers name emotions and calm down after frustration.','研讨会讨论了帮助幼儿说出情绪并在受挫后平静下来的育儿方法。','The workshop discussed parenting strategies / for helping toddlers name emotions / and calm down after frustration.','parenting 指父母照料、教育和养育子女的活动。','研讨会讨论的是养育策略。'),M('The workshop on parenting focused exclusively on repairing cars and never discussed caring for or raising children.','The workshop on parenting focused on ways to care for and guide young children.','parenting 指育儿；修车课程与养育子女无关。','meaning'),[q('What did the workshop discuss?','helping toddlers name emotions and calm down','repairing a damaged parkway','choosing a parasol for a walk','研讨会讨论了育儿方法。'),q('What does parenting involve?','caring for and raising children','measuring a geometric curve','packing a parcel for delivery','parenting 是照料和养育子女。',1,'meaning'),q('Which person is engaged in parenting?','a caregiver helping a child learn routines and manage feelings','a courier wrapping a camera for delivery','a geologist mapping an ancient continent','帮助孩子学习日常习惯与管理情绪属于育儿。',1,'context'),q('How is parenting related to parent?','it is the activity noun formed from the verb parent','it is the plural of parent','it is an adjective meaning equal','parenting 是由 parent 动词构成的活动名词。',1,'word-formation')]);
P('parish','Parish came through French and Late Latin from Greek paroikia, a district or community; it can mean a church district or a local government unit.',[C('parish.s1','（教会）教区','The parish priest visited the small villages within the parish before the winter services began.','冬季礼拜开始前，教区牧师走访了教区范围内的小村庄。','The parish priest visited the small villages / within the parish / before the winter services began.','parish 作名词可指拥有本地教堂和牧师的教会区域。','牧师在该教区内巡访村庄。'),C('parish.s2','（英国等的）行政小区；堂区','The council published a notice explaining which parish would maintain the footpath and collect local fees.','委员会发布通知，说明由哪个行政小区维护步道并征收地方费用。','The council published a notice / explaining which parish would maintain the footpath / and collect local fees.','在英国等地，parish 也可指承担地方治理职能的最小行政区。','维护公共步道和地方收费属于行政事务。')],M('The council assigned the footpath to a parish, but the notice said that parish had no local boundaries or administrative responsibilities.','The council assigned the footpath to a parish, the local unit responsible for maintaining it and collecting fees.','行政义 parish 有边界并承担地方管理职责，不是没有行政职能的抽象名称。','meaning'),[q('Where did the parish priest visit villages?','within the church district','in a different country','inside the town’s airport','牧师走访了本教区内的村庄。',1,'context'),q('What responsibility did the local-government parish have?','maintaining the footpath and collecting local fees','conducting a scientific experiment on telepathy','teaching a theater performance','地方行政小区负责维护步道并收取地方费用。',2,'context'),q('Which meaning of parish fits “the parish church”?','a church district or community','a scientific model','a package delivered to a home','parish church 与教会区域相关。',1,'meaning'),q('What did the Greek source paroikia refer to?','a neighborhood or community','a sunshade','a short sharp breath','paroikia 与邻里或教区共同体有关。',1,'word-formation')]);
P('parisyllabic','Parisyllabic is a learned formation from Latin par, “equal,” and syllabic; it describes words or stems with the same syllable count across forms.',C('parisyllabic.s1','音节数相同的','The linguist called the noun parisyllabic because its singular and plural forms had the same number of syllables.','语言学家称这个名词为音节数相同的，因为它的单数和复数形式音节数一样。','The linguist called the noun parisyllabic / because its singular and plural forms / had the same number of syllables.','parisyllabic 是语言学术语，指相关词形的音节数相同。','比较单数和复数的音节数。'),M('The forms were called parisyllabic even though the singular had two syllables and the plural had five.','The forms were called parisyllabic because the singular and plural each had three syllables.','parisyllabic 意为相关形式音节数相同；二和五不相等。','meaning'),[q('Why was the noun called parisyllabic?','its singular and plural had equal syllable counts','its plural had three more letters','the forms had unrelated meanings','单复数形式的音节数相等。'),q('What does parisyllabic mean?','having the same number of syllables in the relevant forms','having an even number of letters in every word','having no syllables at all','该术语指相关形式音节数相同。',1,'meaning'),q('Which pair is parisyllabic?','a form with two syllables and its related form with two syllables','a one-syllable form and a four-syllable form','two words with the same first letter but different syllable counts','两个形式各有两音节，符合该定义。',1,'context'),q('What does Latin par mean in the word’s formation?','equal','speech','garden','拉丁语 par 表示“相等”。',1,'word-formation')]);
P('park','Park came through Old French parc, probably from a Germanic word for an enclosure; it can mean a public green, a designated area, park a vehicle, or put aside.',[C('park.s1','公园；园林','Families spread blankets on the grass in the public park while children played beneath the old trees.','孩子们在老树下玩耍时，家人们在公园草地上铺开毯子。','Families spread blankets on the grass / in the public park / while children played beneath the old trees.','park 作名词可指供公众休闲、散步或游玩的绿地。','草地和儿童游戏说明是公共公园。'),C('park.s2','停车场；园区','The science park contains several research buildings, a cafeteria, and a visitor center.','科学园区内有几栋研究楼、一家食堂和一个游客中心。','The science park contains several research buildings / a cafeteria / and a visitor center.','park 也可指为特定用途划出的区域，如停车场或产业园。','研究建筑集中于一个园区。'),C('park.s3','停（车）','Please park the van behind the marked line so the loading entrance remains clear.','请把货车停在标线后面，以免堵住装卸入口。','Please park the van behind the marked line / so the loading entrance / remains clear.','park 作动词可指将车辆停放一段时间。','车辆停在指定标线后。'),C('park.s4','搁置；暂放','Let’s park the budget question until the finance director joins the meeting.','我们先把预算问题搁置，等财务主管加入会议后再讨论。','Let’s park the budget question / until the finance director joins / the meeting.','park 作动词还可比喻暂时搁置问题或把物品放在一旁。','讨论暂缓，等合适人员到场再继续。')],M('The driver parked the van in the marked space, but the loading entrance remained completely blocked by that same van.','The driver parked the van behind the marked line, leaving the loading entrance clear.','指定区域停车应避免堵住装卸入口；原句所说结果与目的相反。','meaning'),[q('Where did the families spread their blankets?','on the grass in the public park','inside a research laboratory','behind the loading entrance','家人在公共公园草地上铺毯子。',1,'context'),q('What can visitors find in the science park?','research buildings and a visitor center','a single private garden with no buildings','only a marked vehicle space','园区里有研究楼、食堂和游客中心。',2,'context'),q('What does park mean in “park the van”?','leave the vehicle in a place for a time','walk through a green public area','cancel the van’s registration permanently','这里 park 指停车。',3,'meaning'),q('What does “park the budget question” mean?','set it aside temporarily for later discussion','move a vehicle beside the meeting table','approve the budget immediately','比喻用法表示暂时搁置问题。',4,'meaning')]);
P('parking','Parking is the verbal noun from park; it names leaving a vehicle in a place and can describe a place intended for parked vehicles.',[C('parking.s1','停车','The station charges a small fee for parking overnight in the covered garage.','车站在有顶车库过夜停车要收取少量费用。','The station charges a small fee / for parking overnight / in the covered garage.','parking 作名词可指把车辆停放一段时间的行为。','overnight 和收费车库体现停车行为。'),C('parking.s2','停车用的','The apartment includes one parking space beside the entrance for residents.','这套公寓在入口旁为住户配有一个停车位。','The apartment includes one parking space / beside the entrance / for residents.','parking 可作定语，表示供车辆停放使用的。','parking 修饰 space，说明用途。')],M('The building advertised a parking space, but the sign said residents were forbidden to leave any vehicle there.','The building advertised a parking space where residents could leave one vehicle.','parking space 是供车辆停放的位置；禁止停放与名称相矛盾。','meaning'),[q('What does the station charge for?','leaving a vehicle overnight in the garage','using the public park during the day','entering the research library','车站对过夜停车收取费用。',1,'context'),q('What is included with the apartment?','one space for residents’ vehicles','a storage parcel for books','a private bus route','公寓配有一个停车位。',2,'context'),q('What does parking mean in “parking overnight”?','the act of leaving a vehicle somewhere','the act of repairing a road','the act of walking through a park','parking 指停车行为。',1,'meaning'),q('What does parking modify in “parking space”?','space, describing its intended use','apartment, describing its age','entrance, describing its color','parking 修饰 space，表示该位置用于停车。',2,'grammar')]);
P('parkway','Parkway combines park and way; it names a landscaped road, often designed to pass through parkland or to provide a scenic route.',C('parkway.s1','公园式道路','The new parkway curved through the greenbelt, with trees and walking paths separating it from nearby homes.','新公园式道路蜿蜒穿过绿地带，树木和步道将它与附近住宅隔开。','The new parkway curved through the greenbelt / with trees and walking paths / separating it from nearby homes.','parkway 指带有景观绿化的道路，常穿过公园地带或提供风景路线。','道路两旁有树木和步道。'),M('The city called the road a parkway, although it was a narrow indoor corridor with no vehicle access or landscaping.','The city called the road a parkway because it passed through landscaped parkland with trees and paths.','parkway 是景观道路，不是室内走廊。','meaning'),[q('Where did the parkway pass?','through a greenbelt with trees and walking paths','through a shopping mall corridor','across the floor of a library','道路穿过有树木和步道的绿地带。'),q('What is a parkway?','a landscaped road, often through parkland','a trail reserved only for bicycles indoors','a space intended for parking one car','parkway 是带景观绿化的道路。',1,'meaning'),q('Why were nearby homes separated from the road?','trees and paths formed a landscaped buffer','the road passed through the houses','the homes were located inside the tunnel','树木和步道把道路与住宅隔开。',1,'context'),q('Which parts form parkway?','park and way','par and able','parch and ment','parkway 是由 park 和 way 组成的复合词。',1,'word-formation')]);
P('parlance','Parlance came from French parlance, from parler, “to speak”; it means the vocabulary or style used by a profession or community.',C('parlance.s1','用语；说法','In legal parlance, “consideration” has a specific meaning that differs from its everyday use.','在法律用语中，“consideration”有特定含义，与日常用法不同。','In legal parlance / “consideration” has a specific meaning / that differs from its everyday use.','parlance 指某职业或群体使用的词汇和表达方式。','法律群体赋予该词专业含义。'),M('The judge explained the term in legal parlance, but insisted that the phrase had no specialized meaning in law.','The judge explained that in legal parlance the phrase has a specialized meaning.','parlance 指特定群体的用语；若毫无专业含义，就不能这样说明。','meaning'),[q('What does “consideration” mean in the example?','it has a legal meaning distinct from everyday use','it always means a thoughtful gift','it names a landscaped road','法律用语中的词义与日常用法不同。'),q('What is parlance?','the vocabulary and style used by a profession or community','a type of plant that feeds on a host','a written story with a moral','parlance 是某专业或群体的表达方式。',1,'meaning'),q('Which phrase uses parlance naturally?','In medical parlance, the term has a precise definition.','In medical parlance, the hospital has a parking lot.','Parlance the nurse carefully checked the patient.','medical parlance 指医学专业用语。',1,'usage'),q('Which French verb is linked to parlance?','parler, “to speak”','parer, “to prepare or trim”','parquer, “to enclose”','parlance 源自 parler“说话”。',1,'word-formation')]);
})();
